INSERT INTO `mdl_assign` (`id`, `course`, `name`, `intro`, `introformat`, `alwaysshowdescription`, `nosubmissions`, `submissiondrafts`, `sendnotifications`, `sendlatenotifications`, `duedate`, `allowsubmissionsfromdate`, `grade`, `timemodified`, `requiresubmissionstatement`, `completionsubmit`, `cutoffdate`, `gradingduedate`, `teamsubmission`, `requireallteammemberssubmit`, `teamsubmissiongroupingid`, `blindmarking`, `hidegrader`, `revealidentities`, `attemptreopenmethod`, `maxattempts`, `markingworkflow`, `markingallocation`, `markinganonymous`, `sendstudentnotifications`, `preventsubmissionnotingroup`, `activity`, `activityformat`, `timelimit`, `submissionattachments`, `gradepenalty`) VALUES
(3, 3, 'Tugas', '<p>Tugas Individu : Rangkuman Ringkasan dan Analisis Materi<br><br></p>\r\n<h3 data-section-id=\"fu8zi8\" data-start=\"379\" data-end=\"399\">Deskripsi Tugas:</h3>\r\n<p data-start=\"401\" data-end=\"428\">Setelah mempelajari materi:</p>\r\n<ol data-start=\"430\" data-end=\"527\">\r\n<li data-section-id=\"1nydsq6\" data-start=\"430\" data-end=\"464\">Dasar-Dasar Jaringan Komputer</li>\r\n<li data-section-id=\"d7gzzg\" data-start=\"465\" data-end=\"501\">Instalasi Sistem Operasi Server</li>\r\n<li data-section-id=\"on6s9c\" data-start=\"502\" data-end=\"527\">Konfigurasi Jaringan</li>\r\n</ol>\r\n<p data-start=\"529\" data-end=\"623\">Peserta didik diminta untuk membuat ringkasan dan penjelasan singkat mengenai ketiga topik tersebut</p>', 1, 1, 0, 0, 0, 0, 1783443600, 1773248400, 100, 1775056062, 0, 1, 0, 1786726800, 0, 0, 0, 0, 0, 0, 'untilpass', 1, 0, 0, 0, 1, 0, '<h3 data-section-id=\"1cgk1bg\" data-start=\"630\" data-end=\"655\">Ketentuan Pengerjaan:</h3>\r\n<p data-start=\"657\" data-end=\"698\">Buatlah jawaban dengan ketentuan berikut:</p>\r\n<p data-start=\"700\" data-end=\"736\"><strong data-start=\"700\" data-end=\"736\">1. Dasar-Dasar Jaringan Komputer</strong></p>\r\n<p>    a. Jelaskan pengertian jaringan komputer.</p>\r\n<p>    b. Sebutkan minimal 3 perangkat jaringan beserta fungsinya.</p>\r\n<p data-start=\"838\" data-end=\"876\"><strong data-start=\"838\" data-end=\"876\">2. Instalasi Sistem Operasi Server</strong></p>\r\n<p>    a. Jelaskan perbedaan sistem operasi server dan sistem operasi biasa.</p>\r\n<p>    b. Tuliskan langkah umum instalasi server secara singkat.</p>\r\n<p data-start=\"1004\" data-end=\"1031\"><strong data-start=\"1004\" data-end=\"1031\">3. Konfigurasi Jaringan</strong></p>\r\n<p>    a. Jelaskan fungsi IP Address.<br>    b. Berikan contoh penulisan IP Address yang benar.<br><br><br></p>\r\n<h3 data-section-id=\"tiutlb\" data-start=\"1118\" data-end=\"1137\">Format Jawaban:</h3>\r\n<p>1. Minimal 2 halaman<br>2. Diketik rapi<br>3.Format PDF<br>4. Bahasa formal dan jelas<br><br></p>\r\n<h3 data-section-id=\"11758v2\" data-start=\"1218\" data-end=\"1234\">Pengumpulan:</h3>\r\n<p data-start=\"1235\" data-end=\"1314\">Upload file dalam bentuk PDF melalui Moodle sesuai waktu yang telah ditentukan<br><br></p>\r\n<h3 data-section-id=\"vmb4xq\" data-start=\"1321\" data-end=\"1344\">Kriteria Penilaian:</h3>\r\n<ul data-start=\"1345\" data-end=\"1446\">\r\n<li data-section-id=\"4wkxz2\" data-start=\"1345\" data-end=\"1368\">Ketepatan isi jawaban</li>\r\n<li data-section-id=\"17h99zk\" data-start=\"1369\" data-end=\"1395\">Kesesuaian dengan materi</li>\r\n<li data-section-id=\"1x3x9zo\" data-start=\"1396\" data-end=\"1416\">Kerapian penulisan</li>\r\n<li data-section-id=\"1vwllgj\" data-start=\"1417\" data-end=\"1446\">Ketepatan waktu pengumpulan</li>\r\n</ul>\r\n<p><br><br></p>', 1, 0, 0, 0),
(52, 7, 'Tugas Challenge 1', '', 1, 1, 0, 0, 0, 0, 1778778000, 1778691600, 100, 1778604980, 0, 1, 0, 1778950800, 0, 0, 0, 0, 0, 0, 'untilpass', 1, 0, 0, 0, 1, 0, '<p>Buatlah laporan ....</p>', 1, 0, 0, 0),
(53, 7, 'Tugas Challenge 2', '', 1, 1, 0, 0, 0, 0, 1779210000, 1779037200, 100, 1778605029, 0, 1, 0, 1779296400, 0, 0, 0, 0, 0, 0, 'untilpass', 1, 0, 0, 0, 1, 0, '', 1, 0, 0, 0),
(54, 7, 'Tugas Challenge 3', '', 1, 1, 0, 0, 0, 0, 1779642000, 1779382800, 100, 1778605068, 0, 1, 0, 1779728400, 0, 0, 0, 0, 0, 0, 'untilpass', 1, 0, 0, 0, 1, 0, '', 1, 0, 0, 0),
(55, 8, 'Tugas Materi 1', '<p>Pada materi dalam bentuk pdf yang tertera siswa diharap mengerjakan tugas untuk mengukur seberapa tahu pengetahuan yang sudah di pelajari dalam materi pdf yang disajikan</p>', 1, 1, 0, 1, 0, 0, 1779210000, 1773766800, 100, 1779173770, 1, 1, 0, 1779296400, 0, 0, 0, 0, 0, 0, 'untilpass', 1, 0, 0, 0, 1, 0, '<p>Buatlah rangkuman dari materi yang sudah disajikan lalu buat video kalian mempresentasikan hasil dari rangkuman sendiri!</p>', 1, 0, 0, 0),
(56, 8, 'Tugas Materi 2', '<p>Siswa diharap mengerjakan tugas dari media video yang sudah disajikan</p>', 1, 1, 0, 0, 0, 0, 1779210000, 1773766800, 100, 1779173789, 0, 1, 0, 1779296400, 0, 0, 0, 0, 0, 0, 'untilpass', 1, 0, 0, 0, 1, 0, '<p>Buatlah laporan tentang video yang sudah ada maksimal 4 halaman berbentuk file pdf</p>', 1, 0, 0, 0),
(57, 8, 'Tugas Materi 3', '<p>Dari hasil final materi yang sudah ada di LMS siswa diharap memahami semua materi yang disajikan selama ini</p>', 1, 1, 0, 0, 0, 0, 1779210000, 1773766800, 100, 1779173803, 0, 1, 0, 1779296400, 0, 0, 0, 0, 0, 0, 'untilpass', 1, 0, 0, 0, 1, 0, '<p>Buat makalah yang membahas tentang teknologi maksimal 7 halaman dengan sumber yang jelas dan valid</p>', 1, 0, 0, 0);
