(23, 'H5P.DocumentExportPage', 'Document Export Page', 1, 5, 19, 0, 0, '', 'dist/h5p-document-export-page.js', 'dist/h5p-document-export-page.css', '', '[\n  {\n    \"name\": \"description\",\n    \"label\": \"Description\",\n    \"importance\": \"medium\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Description of the export page.\",\n    \"default\": \"On this page you can choose to export your text, goals and goals assessments.\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ],\n    \"optional\": true\n  },\n  {\n    \"name\": \"createDocumentLabel\",\n    \"label\": \"Create document button label\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text that will be displayed on the \\\"Create document\\\"-button.\",\n    \"default\": \"Create document\"\n  },\n  {\n    \"name\": \"submitTextLabel\",\n    \"label\": \"Submit text button\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text that will be displayed on the \\\"Submit\\\"-button.\",\n    \"default\": \"Submit\"\n  },\n  {\n    \"name\": \"submitSuccessTextLabel\",\n    \"type\": \"text\",\n    \"label\": \"Submit success label\",\n    \"optional\": false,\n    \"default\": \"Your report was submitted successfully!\"\n  },\n  {\n    \"name\": \"selectAllTextLabel\",\n    \"label\": \"Select all exportable text button label\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text that will be displayed on the \\\"Select all text\\\"-button.\",\n    \"default\": \"Select\"\n  },\n  {\n    \"name\": \"exportTextLabel\",\n    \"label\": \"Export text button label\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text that will be displayed on the \\\"Export text\\\"-button.\",\n    \"default\": \"Export\"\n  },\n  {\n    \"name\": \"helpTextLabel\",\n    \"label\": \"Label for help text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Label for showing additional helpful information to the user.\",\n    \"default\": \"More information\"\n  },\n  {\n    \"name\": \"helpText\",\n    \"label\": \"Fill in additional help information\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Here you can fill in additional helpful information for the user.\",\n    \"enterMode\": \"p\",\n    \"optional\": true,\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ]\n  },\n  {\n    \"name\": \"requiresInputErrorMessage\",\n    \"label\": \"Required input missing text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"An error message which will be displayed if one or more required input fields have not been filled. @pages will be replaced with the titles of affected pages.\",\n    \"default\": \"The following pages contain required fields that need to be filled in order to review or submit this document: @pages\"\n  }\n]\n', NULL, 1, 27, NULL, NULL, NULL, 1),
(24, 'H5P.GoalsAssessmentPage', 'Goals assessment page', 1, 4, 17, 0, 0, '', 'goals-assessment-page.js', 'goals-assessment-page.css', '', '[\n  {\n    \"name\": \"description\",\n    \"label\": \"Description\",\n    \"importance\": \"medium\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Description of the goals assessment page.\",\n    \"default\": \"Rate the goals that you have chosen in the goals page.\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ],\n    \"optional\": true\n  },\n  {\n    \"name\": \"lowRating\",\n    \"label\": \"Low rating text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text for worst rating.\",\n    \"default\": \"Learned little\"\n  },\n  {\n    \"name\": \"midRating\",\n    \"label\": \"Medium rating text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text for middle rating.\",\n    \"default\": \"Learned something\"\n  },\n  {\n    \"name\": \"highRating\",\n    \"label\": \"High rating text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text for great rating.\",\n    \"default\": \"Learned a lot\"\n  },\n  {\n    \"name\": \"noGoalsText\",\n    \"label\": \"No goals text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Feedback text when no goals have been created.\",\n    \"default\": \"You have not chosen any goals yet.\"\n  },\n  {\n    \"name\": \"helpTextLabel\",\n    \"label\": \"Label for help text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Label for showing additional helpful information to the user.\",\n    \"default\": \"More information\"\n  },\n  {\n    \"name\": \"helpText\",\n    \"label\": \"Fill in additional help information\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Here you can fill in additional helpful information for the user.\",\n    \"enterMode\": \"p\",\n    \"optional\": true,\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ]\n  },\n  {\n    \"name\": \"legendHeader\",\n    \"label\": \"Legend header\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"default\": \"Possible ratings:\"\n  },\n  {\n    \"name\": \"goalHeader\",\n    \"label\": \"Goal header\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"default\": \"Goals\"\n  },\n  {\n    \"name\": \"ratingHeader\",\n    \"label\": \"Rating header\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"default\": \"Rating\"\n  }\n]', NULL, 1, 19, NULL, NULL, NULL, 1),
(25, 'H5P.GoalsPage', 'Goals page', 1, 5, 21, 0, 0, '', 'goals-page.js, goal-instance.js', 'goals-page.css', '', '[\n  {\n    \"name\": \"description\",\n    \"label\": \"Description\",\n    \"importance\": \"medium\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Description of the goals page.\",\n    \"default\": \"Insert the goals that you have chosen to work with.\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ],\n    \"optional\": true\n  },\n  {\n    \"name\": \"defineGoalText\",\n    \"label\": \"Define goal link text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text that will be displayed on the button for creating a new goal.\",\n    \"default\": \"Create a new goal\"\n  },\n  {\n    \"name\": \"definedGoalLabel\",\n    \"label\": \"Label for a user defined goal\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text that will be displayed as label on a user created goal.\",\n    \"default\": \"User defined goal\"\n  },\n  {\n    \"name\": \"defineGoalPlaceholder\",\n    \"label\": \"Define goal placeholder\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text that will be displayed as a placeholder when creating a new goal.\",\n    \"default\": \"Write here...\"\n  },\n  {\n    \"name\": \"goalsAddedText\",\n    \"label\": \"Text indicating how many goals has been added\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"default\": \"Goals added:\",\n    \"description\": \"This text will follow after the amount of goals that is currently created, example: \'Goals added: 5\' where \'Goals added:\' is this text.\"\n  },\n  {\n    \"name\": \"specifyGoalText\",\n    \"label\": \"Text for \\\"Specify goal\\\"-button\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"default\": \"Specification\"\n  },\n  {\n    \"name\": \"removeGoalText\",\n    \"label\": \"Text for \\\"Remove goal\\\"-button\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"default\": \"Remove Goal\"\n  },\n  {\n    \"name\": \"helpTextLabel\",\n    \"label\": \"Label for help text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Label for showing additional helpful information to the user.\",\n    \"default\": \"More information\"\n  },\n  {\n    \"name\": \"helpText\",\n    \"label\": \"Fill in additional help information\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Here you can fill in additional helpful information for the user.\",\n    \"enterMode\": \"p\",\n    \"optional\": true,\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ]\n  },\n  {\n    \"name\": \"goalDeletionConfirmation\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"importance\": \"low\",\n    \"label\": \"Localize goal deletion confirmation\",\n    \"fields\": [\n      {\n        \"name\": \"header\",\n        \"type\": \"text\",\n        \"label\": \"Header\",\n        \"optional\": false,\n        \"default\": \"Confirm deletion\"\n      },\n      {\n        \"name\": \"message\",\n        \"type\": \"text\",\n        \"label\": \"Message\",\n        \"optional\": false,\n        \"default\": \"Are you sure you want to delete this goal?\"\n      },\n      {\n        \"name\": \"cancelLabel\",\n        \"type\": \"text\",\n        \"label\": \"Cancel button label\",\n        \"optional\": false,\n        \"default\": \"Cancel\"\n      },\n      {\n        \"name\": \"confirmLabel\",\n        \"type\": \"text\",\n        \"label\": \"Confirm button label\",\n        \"optional\": false,\n        \"default\": \"Confirm\"\n      }\n    ]\n  }\n]\n', NULL, 1, 19, NULL, NULL, NULL, 1),
(26, 'H5P.Image', 'Image', 1, 1, 22, 0, 0, '', 'image.js', 'image.css', '', '[\n  {\n    \"name\": \"file\",\n    \"type\": \"image\",\n    \"label\": \"Image\",\n    \"importance\": \"high\",\n    \"disableCopyright\": true\n  },\n  {\n    \"name\": \"decorative\",\n    \"type\": \"boolean\",\n    \"label\": \"Decorative only\",\n    \"default\": false,\n    \"description\": \"Enable this option if the image is purely decorative and does not add any information to the content on the page. It will be ignored by screen readers and not given any alternative text.\"\n  },\n  {\n    \"name\": \"alt\",\n    \"type\": \"text\",\n    \"label\": \"Alternative text\",\n    \"importance\": \"high\",\n    \"description\": \"Required. If the browser can\'t load the image this text will be displayed instead. Also used by \\\"text-to-speech\\\" readers.\",\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"decorative\",\n          \"equals\": false\n        }\n      ],\n      \"nullWhenHidden\": true\n    }\n  },\n  {\n    \"name\": \"title\",\n    \"type\": \"text\",\n    \"label\": \"Hover text\",\n    \"importance\": \"low\",\n    \"description\": \"Optional. This text is displayed when the users hover their pointing device over the image.\",\n    \"optional\": true\n  },\n  {\n    \"name\": \"contentName\",\n    \"type\": \"text\",\n    \"label\": \"Image content name\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Image\"\n  },\n  {\n    \"name\": \"expandImage\",\n    \"type\": \"text\",\n    \"label\": \"Expand Image\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Expand Image\"\n  },\n  {\n    \"name\": \"minimizeImage\",\n    \"type\": \"text\",\n    \"label\": \"Minimize Image\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Minimize Image\"\n  }\n]\n', NULL, 1, 19, '{\"disable\":false,\"disableExtraTitleField\":true}', NULL, NULL, 1),
(27, 'H5P.StandardPage', 'Standard page', 1, 5, 16, 0, 0, '', 'standard-page.js', 'standard-page.css', '', '[\n  {\n    \"name\": \"elementList\",\n    \"label\": \"Elements\",\n    \"importance\": \"high\",\n    \"type\": \"list\",\n    \"entity\": \"element\",\n    \"field\": {\n      \"name\": \"element\",\n      \"type\": \"library\",\n      \"label\": \"Element type\",\n      \"importance\": \"high\",\n      \"description\": \"Library for this page.\",\n      \"options\": [\n        \"H5P.Text 1.1\",\n        \"H5P.TextInputField 1.2\",\n        \"H5P.Image 1.1\",\n        \"H5P.Accordion 1.0\"\n      ]\n    }\n  },\n  {\n    \"name\": \"helpTextLabel\",\n    \"label\": \"Label for help text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Label for showing additional helpful information to the user.\",\n    \"default\": \"More information\"\n  },\n  {\n    \"name\": \"helpText\",\n    \"label\": \"Fill in additional help information\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Here you can fill in additional information for the user, which will be available when clicked.\",\n    \"enterMode\": \"p\",\n    \"optional\": true,\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ]\n  }\n]\n', NULL, 1, 19, NULL, NULL, NULL, 1),
(28, 'H5P.Text', 'Text', 1, 1, 17, 0, 0, '', 'scripts/text.js', 'styles/text.css', '', '[\n  {\n    \"name\": \"text\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"importance\": \"high\",\n    \"label\": \"Text\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"del\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ]\n  }\n]\n', NULL, NULL, NULL, '{\"disable\":false,\"disableExtraTitleField\":true}', NULL, NULL, 1),
(29, 'H5P.TextInputField', 'Text input field editor element', 1, 2, 17, 0, 0, '', 'text-input-field.js, xapi-generator.js', 'text-input-field.css', '', '[\n  {\n    \"name\": \"taskDescription\",\n    \"label\": \"Description of inputfield\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"importance\": \"high\",\n    \"description\": \"Description of what the user should input.\",\n    \"enterMode\": \"div\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ],\n    \"optional\": true\n  },\n  {\n    \"name\": \"placeholderText\",\n    \"label\": \"Placeholder text\",\n    \"type\": \"text\",\n    \"description\": \"Example value or other placeholder text. Should not be used to replace the description of input-field, this value may not be available for screen-readers and also disappears when users start typing.\",\n    \"importance\": \"low\",\n    \"optional\": true\n  },\n  {\n    \"name\": \"maximumLength\",\n    \"label\": \"Maximum text length\",\n    \"type\": \"number\",\n    \"description\": \"Maximum number of characters for the text.\",\n    \"importance\": \"low\",\n    \"optional\": true,\n    \"min\": \"0\"\n  },\n  {\n    \"name\": \"inputFieldSize\",\n    \"label\": \"Input field size\",\n    \"type\": \"select\",\n    \"importance\": \"low\",\n    \"description\": \"The size of the input field in amount of lines it will cover.\",\n    \"options\": [\n      {\n        \"value\": \"1\",\n        \"label\": \"1 line\"\n      },\n      {\n        \"value\": \"3\",\n        \"label\": \"3 lines\"\n      },\n      {\n        \"value\": \"10\",\n        \"label\": \"10 lines\"\n      }\n    ],\n    \"default\": \"1\"\n  },\n  {\n    \"name\": \"requiredField\",\n    \"label\": \"Required field\",\n    \"type\": \"boolean\",\n    \"importance\": \"low\",\n    \"default\": false,\n    \"optional\": true,\n    \"description\": \"Check to make this field required, the user must answer all required fields to be able to export a document.\"\n  },\n  {\n    \"name\": \"remainingChars\",\n    \"type\": \"text\",\n    \"label\": \"Remaining characters\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Remaining characters: @chars\",\n    \"description\": \"Message for remaining characters. You can use @chars which will be replaced by the corresponding number.\"\n  }\n]', NULL, 1, 27, '{\"disable\":true,\"disableExtraTitleField\":true}', NULL, NULL, 1),
