INSERT INTO `mdl_h5p_libraries` (`id`, `machinename`, `title`, `majorversion`, `minorversion`, `patchversion`, `runnable`, `fullscreen`, `embedtypes`, `preloadedjs`, `preloadedcss`, `droplibrarycss`, `semantics`, `addto`, `coremajor`, `coreminor`, `metadatasettings`, `tutorial`, `example`, `enabled`) VALUES
(40, 'H5P.DragText', 'Drag the Words', 1, 10, 17, 1, 0, 'iframe', 'dist/h5p-drag-text.js', 'dist/h5p-drag-text.css', '', '[\n  {\n    \"name\": \"media\",\n    \"type\": \"group\",\n    \"label\": \"Media\",\n    \"importance\": \"medium\",\n    \"fields\": [\n      {\n        \"name\": \"type\",\n        \"type\": \"library\",\n        \"label\": \"Type\",\n        \"importance\": \"medium\",\n        \"options\": [\n          \"H5P.Image 1.1\",\n          \"H5P.Video 1.6\",\n          \"H5P.Audio 1.5\"\n        ],\n        \"optional\": true,\n        \"description\": \"Optional media to display above the question.\"\n      },\n      {\n        \"name\": \"disableImageZooming\",\n        \"type\": \"boolean\",\n        \"label\": \"Disable image zooming\",\n        \"importance\": \"low\",\n        \"default\": false,\n        \"optional\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"type\",\n              \"equals\": \"H5P.Image 1.1\"\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"label\": \"Task description\",\n    \"importance\": \"high\",\n    \"name\": \"taskDescription\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Describe how the user should solve the task.\",\n    \"default\": \"Drag the words into the correct boxes\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ]\n  },\n  {\n    \"label\": \"Text\",\n    \"importance\": \"high\",\n    \"name\": \"textField\",\n    \"type\": \"text\",\n    \"widget\": \"textarea\",\n    \"placeholder\": \"*Oslo* is the capital of Norway, *Stockholm* is the capital of Sweden and *Copenhagen* is the capital of Denmark. All cities are located in the *Scandinavian:Northern Part of Europe* peninsula.\",\n    \"description\": \"\",\n    \"important\": {\n      \"description\": \"<ul><li>Droppable words are added with an asterisk (*) in front and behind the correct word/phrase.</li><li>You may add a textual tip, using a colon (:) in front of the tip.</li><li>For every empty spot there is only one correct word.</li><li>You may add feedback to be displayed when a task is completed. Use \'\\\\+\' for correct and \'\\\\-\' for incorrect feedback.</li></ul>\",\n      \"example\": \"H5P content may be edited using a *browser:What type of program is Chrome?*. </br> H5P content is *interactive\\\\+Correct! \\\\-Incorrect, try again!*\"\n    }\n  },\n  {\n    \"label\": \"Distractors\",\n    \"importance\": \"high\",\n    \"name\": \"distractors\",\n    \"type\": \"text\",\n    \"optional\": true,\n    \"placeholder\": \"*Reykjavík* *Helsinki*\",\n    \"description\": \"Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text.\"\n  },\n  {\n    \"name\": \"overallFeedback\",\n    \"type\": \"group\",\n    \"label\": \"Overall Feedback\",\n    \"importance\": \"low\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"overallFeedback\",\n        \"type\": \"list\",\n        \"widgets\": [\n          {\n            \"name\": \"RangeList\",\n            \"label\": \"Default\"\n          }\n        ],\n        \"importance\": \"high\",\n        \"label\": \"Define custom feedback for any score range\",\n        \"description\": \"Click the \\\"Add range\\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!\",\n        \"entity\": \"range\",\n        \"min\": 1,\n        \"defaultNum\": 1,\n        \"optional\": true,\n        \"field\": {\n          \"name\": \"overallFeedback\",\n          \"type\": \"group\",\n          \"importance\": \"low\",\n          \"fields\": [\n            {\n              \"name\": \"from\",\n              \"type\": \"number\",\n              \"label\": \"Score Range\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 0,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"to\",\n              \"type\": \"number\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 100,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"feedback\",\n              \"type\": \"text\",\n              \"label\": \"Feedback for defined score range\",\n              \"importance\": \"low\",\n              \"placeholder\": \"Fill in the feedback\",\n              \"optional\": true\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"label\": \"Text for \\\"Check\\\" button\",\n    \"importance\": \"low\",\n    \"name\": \"checkAnswer\",\n    \"type\": \"text\",\n    \"default\": \"Check\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for \\\"Submit\\\" button\",\n    \"importance\": \"low\",\n    \"name\": \"submitAnswer\",\n    \"type\": \"text\",\n    \"default\": \"Submit\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for \\\"Retry\\\" button\",\n    \"importance\": \"low\",\n    \"name\": \"tryAgain\",\n    \"type\": \"text\",\n    \"default\": \"Retry\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for \\\"Show Solution\\\" button\",\n    \"importance\": \"low\",\n    \"name\": \"showSolution\",\n    \"type\": \"text\",\n    \"default\": \"Show solution\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Numbered Drop zone label\",\n    \"importance\": \"low\",\n    \"name\": \"dropZoneIndex\",\n    \"type\": \"text\",\n    \"default\": \"Drop Zone @index.\",\n    \"description\": \"Label used for accessibility, where the Read speaker will read the index of a drop zone. Variable available: @index\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Empty Drop Zone label\",\n    \"importance\": \"low\",\n    \"name\": \"empty\",\n    \"type\": \"text\",\n    \"default\": \"Drop Zone @index is empty.\",\n    \"description\": \"Label used for accessibility, where the Read speaker will read that the drop zone is empty\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Contains Drop Zone label\",\n    \"importance\": \"low\",\n    \"name\": \"contains\",\n    \"type\": \"text\",\n    \"default\": \"Drop Zone @index contains draggable @draggable.\",\n    \"description\": \"Label used for accessibility, where the Read speaker will read that the drop zone contains a draggable\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Draggable elements label\",\n    \"importance\": \"low\",\n    \"name\": \"ariaDraggableIndex\",\n    \"type\": \"text\",\n    \"default\": \"@index of @count draggables.\",\n    \"description\": \"Label used for accessibility, where the Read speaker reads that this is a draggable element. Variable available: @index, @count\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Label for show tip button\",\n    \"importance\": \"low\",\n    \"name\": \"tipLabel\",\n    \"type\": \"text\",\n    \"default\": \"Show tip\",\n    \"description\": \"Label used for accessibility, where the Read speaker reads it before the tip is read out\",\n    \"common\": true\n  },\n  {\n    \"name\": \"correctText\",\n    \"type\": \"text\",\n    \"label\": \"Readspeaker text for correct answer\",\n    \"importance\": \"low\",\n    \"default\": \"Correct!\",\n    \"common\": true\n  },\n  {\n    \"name\": \"incorrectText\",\n    \"type\": \"text\",\n    \"label\": \"Readspeaker text for incorrect answer\",\n    \"importance\": \"low\",\n    \"default\": \"Incorrect!\",\n    \"common\": true\n  },\n  {\n    \"name\": \"resetDropTitle\",\n    \"type\": \"text\",\n    \"label\": \"Confirmation dialog title that user wants to reset a droppable\",\n    \"importance\": \"low\",\n    \"default\": \"Reset drop\",\n    \"common\": true\n  },\n  {\n    \"name\": \"resetDropDescription\",\n    \"type\": \"text\",\n    \"label\": \"Confirmation dialog description that user wants to reset a droppable\",\n    \"importance\": \"low\",\n    \"default\": \"Are you sure you want to reset this drop zone?\",\n    \"common\": true\n  },\n  {\n    \"name\": \"grabbed\",\n    \"type\": \"text\",\n    \"label\": \"Label used for accessibility, where the read speaker indicates that dragging is initiated\",\n    \"importance\": \"low\",\n    \"default\": \"Draggable is grabbed.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"cancelledDragging\",\n    \"type\": \"text\",\n    \"label\": \"Label used for accessibility, where the read speaker indicates that dragging is canceled\",\n    \"importance\": \"low\",\n    \"default\": \"Cancelled dragging.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"correctAnswer\",\n    \"type\": \"text\",\n    \"label\": \"Label used for accessibility, where the read speaker indicates that a text is the correct answer\",\n    \"importance\": \"low\",\n    \"default\": \"Correct answer:\",\n    \"common\": true\n  },\n  {\n    \"name\": \"feedbackHeader\",\n    \"type\": \"text\",\n    \"label\": \"Header for panel containing feedback for correct/incorrect answers\",\n    \"importance\": \"low\",\n    \"default\": \"Feedback\",\n    \"common\": true\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings.\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you control how the task behaves.\",\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"label\": \"Enable \\\"Retry\\\"\",\n        \"importance\": \"low\",\n        \"name\": \"enableRetry\",\n        \"type\": \"boolean\",\n        \"default\": true\n      },\n      {\n        \"label\": \"Enable \\\"Show Solution\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"enableSolutionsButton\",\n        \"type\": \"boolean\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableCheckButton\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable \\\"Check\\\" button\",\n        \"widget\": \"none\",\n        \"importance\": \"low\",\n        \"default\": true,\n        \"optional\": true\n      },\n      {\n        \"label\": \"Instant feedback\",\n        \"importance\": \"low\",\n        \"name\": \"instantFeedback\",\n        \"type\": \"boolean\",\n        \"default\": false,\n        \"optional\": true\n      }\n    ]\n  },\n  {\n    \"name\": \"scoreBarLabel\",\n    \"type\": \"text\",\n    \"label\": \"Textual representation of the score bar for those using a readspeaker\",\n    \"default\": \"You got :num out of :total points\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"name\": \"a11yCheck\",\n    \"type\": \"text\",\n    \"label\": \"Assistive technology label for \\\"Check\\\" button\",\n    \"default\": \"Check the answers. The responses will be marked as correct, incorrect, or unanswered.\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"name\": \"a11yShowSolution\",\n    \"type\": \"text\",\n    \"label\": \"Assistive technology label for \\\"Show Solution\\\" button\",\n    \"default\": \"Show the solution. The task will be marked with its correct solution.\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"name\": \"a11yRetry\",\n    \"type\": \"text\",\n    \"label\": \"Assistive technology label for \\\"Retry\\\" button\",\n    \"default\": \"Retry the task. Reset all responses and start the task over again.\",\n    \"importance\": \"low\",\n    \"common\": true\n  }\n]', NULL, 1, 19, NULL, 'https://h5p.org/documentation/content-author-guide/tutorials-for-authors/drag-the-words', 'https://h5p.org/drag-the-words', 1),
(41, 'H5P.ImageHotspotQuestion', 'Find the Hotspot', 1, 8, 22, 1, 0, '', 'image-hotspot-question.js', 'image-hotspot-question.css', '', '[\n  {\n    \"name\": \"imageHotspotQuestion\",\n    \"type\": \"group\",\n    \"widget\": \"wizard\",\n    \"label\": \"Image Hotspot Question Editor\",\n    \"importance\": \"high\",\n    \"fields\": [\n      {\n        \"name\": \"backgroundImageSettings\",\n        \"type\": \"group\",\n        \"label\": \"Background image\",\n        \"importance\": \"high\",\n        \"fields\": [\n          {\n            \"name\": \"backgroundImage\",\n            \"type\": \"image\",\n            \"label\": \"Background image\",\n            \"importance\": \"high\",\n            \"description\": \"Select an image to use as background for the image hotspot question.\"\n          }\n        ]\n      },\n      {\n        \"name\": \"hotspotSettings\",\n        \"type\": \"group\",\n        \"label\": \"Hotspots\",\n        \"importance\": \"high\",\n        \"widget\": \"imageHotspotQuestion\",\n        \"description\": \"Drag and drop the desired figure from the toolbar to create a new hotspot. Double-click to edit an existing hotspot. Drag the hotspot to move it. Pull the resize handler in the lower right corner to resize.\",\n        \"fields\": [\n          {\n            \"name\": \"taskDescription\",\n            \"type\": \"text\",\n            \"label\": \"Task description\",\n            \"importance\": \"high\",\n            \"description\": \"Instructions to the user.\",\n            \"optional\": true\n          },\n          {\n            \"name\": \"hotspot\",\n            \"type\": \"list\",\n            \"label\": \"Hotspot\",\n            \"importance\": \"high\",\n            \"entity\": \"Hotspot\",\n            \"field\": {\n              \"type\": \"group\",\n              \"label\": \"Hotspot\",\n              \"importance\": \"high\",\n              \"fields\": [\n                {\n                  \"name\": \"userSettings\",\n                  \"type\": \"group\",\n                  \"label\": \"userSettings\",\n                  \"importance\": \"low\",\n                  \"fields\": [\n                    {\n                      \"name\": \"correct\",\n                      \"type\": \"boolean\",\n                      \"label\": \"Correct\",\n                      \"importance\": \"low\",\n                      \"description\": \"There can be multiple correct hotspots. However, the user gets correct/incorrect feedback immediately after first click.\"\n                    },\n                    {\n                      \"name\": \"feedbackText\",\n                      \"type\": \"text\",\n                      \"label\": \"Feedback\",\n                      \"importance\": \"low\",\n                      \"optional\": true\n                    }\n                  ]\n                },\n                {\n                  \"name\": \"computedSettings\",\n                  \"type\": \"group\",\n                  \"label\": \"computedSettings\",\n                  \"importance\": \"low\",\n                  \"fields\": [\n                    {\n                      \"name\": \"x\",\n                      \"type\": \"number\",\n                      \"optional\": true\n                    },\n                    {\n                      \"name\": \"y\",\n                      \"type\": \"number\",\n                      \"optional\": true\n                    },\n                    {\n                      \"name\": \"width\",\n                      \"type\": \"number\",\n                      \"optional\": true\n                    },\n                    {\n                      \"name\": \"height\",\n                      \"type\": \"number\",\n                      \"optional\": true\n                    },\n                    {\n                      \"name\": \"figure\",\n                      \"type\": \"text\",\n                      \"optional\": true\n                    }\n                  ]\n                }\n              ]\n            }\n          },\n          {\n            \"name\": \"noneSelectedFeedback\",\n            \"type\": \"text\",\n            \"label\": \"Feedback if the user selects an empty spot:\",\n            \"importance\": \"low\",\n            \"placeholder\": \"You didn\'t locate any hotspots, try again!\",\n            \"optional\": true\n          },\n          {\n            \"name\": \"showFeedbackAsPopup\",\n            \"type\": \"boolean\",\n            \"label\": \"Show feedback as a popup\",\n            \"importance\": \"low\",\n            \"default\": true,\n            \"optional\": true\n          },\n          {\n            \"label\": \"Localization\",\n            \"name\": \"l10n\",\n            \"type\": \"group\",\n            \"fields\": [\n              {\n                \"name\": \"retryText\",\n                \"label\": \"Retry button text\",\n                \"type\": \"text\",\n                \"default\": \"Retry\",\n                \"optional\": true\n              },\n              {\n                \"name\": \"closeText\",\n                \"label\": \"Close button text\",\n                \"type\": \"text\",\n                \"default\": \"Close\",\n                \"optional\": true\n              }\n            ]\n          }\n        ]\n      }\n    ]\n  },\n  {\n    \"name\": \"scoreBarLabel\",\n    \"type\": \"text\",\n    \"label\": \"Textual representation of the score bar for those using a readspeaker\",\n    \"default\": \"You got :num out of :total points\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"name\": \"a11yRetry\",\n    \"type\": \"text\",\n    \"label\": \"Assistive technology description for \\\"Retry\\\" button\",\n    \"default\": \"Retry the task. Reset all responses and start the task over again.\",\n    \"importance\": \"low\",\n    \"common\": true\n  }\n]', NULL, 1, 23, NULL, NULL, 'https://h5p.org/image-hotspot-question', 1),
(42, 'H5PEditor.ImageHotspotQuestion', 'Image Hotspot Question Editor', 1, 8, 12, 0, 0, '', 'image-hotspot-question-editor.js', 'image-hotspot-question-editor.css', '', '', NULL, 1, 12, NULL, NULL, NULL, 1),
(43, 'H5P.GuessTheAnswer', 'Guess the Answer', 1, 5, 3, 1, 0, 'iframe', 'guess-the-answer.js', 'guess-the-answer.css', '', '[\n  {\n    \"label\": \"Task description\",\n    \"importance\": \"medium\",\n    \"name\": \"taskDescription\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Describe how the user should solve the task.\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ],\n    \"optional\": true\n  },\n  {\n    \"name\": \"media\",\n    \"type\": \"group\",\n    \"label\": \"Media\",\n    \"importance\": \"medium\",\n    \"fields\": [\n      {\n        \"name\": \"type\",\n        \"type\": \"library\",\n        \"label\": \"Type\",\n        \"importance\": \"medium\",\n        \"options\": [\n          \"H5P.Image 1.1\",\n          \"H5P.Video 1.6\"\n        ],\n        \"optional\": true,\n        \"description\": \"Optional media to display above the question.\"\n      }\n    ]\n  },\n  {\n    \"label\": \"Descriptive solution label\",\n    \"importance\": \"low\",\n    \"name\": \"solutionLabel\",\n    \"type\": \"text\",\n    \"widget\": \"textarea\",\n    \"default\": \"Click to see the answer.\",\n    \"description\": \"Clickable text area where the solution will be displayed.\",\n    \"optional\": true\n  },\n  {\n    \"label\": \"Solution text\",\n    \"importance\": \"high\",\n    \"name\": \"solutionText\",\n    \"type\": \"text\",\n    \"widget\": \"textarea\",\n    \"description\": \"The solution for the picture.\"\n  }\n]', NULL, 1, 19, NULL, 'https://h5p.org/tutorial-guess-the-answer', 'https://h5p.org/guess-the-answer', 1),
(44, 'H5P.IFrameEmbed', 'Iframe Embedder', 1, 0, 29, 1, 1, '', 'iframe-embed.js', '', '', '[\n  {\n    \"label\": \"Width\",\n    \"importance\": \"high\",\n    \"name\": \"width\",\n    \"type\": \"text\",\n    \"description\": \"Width of iFrame in CSS compliant format. Default: \\\"500px\\\"\"\n  },\n  {\n    \"label\": \"Minimum width\",\n    \"importance\": \"high\",\n    \"name\": \"minWidth\",\n    \"type\": \"text\",\n    \"description\": \"Minimum width of iFrame in CSS compliant format. Default: \\\"300px\\\"\"\n  },\n  {\n    \"label\": \"Height\",\n    \"name\": \"height\",\n    \"type\": \"text\",\n    \"description\": \"Height of iFrame in CSS compliant format. Default: \\\"500px\\\"\"\n  },\n  {\n    \"label\": \"Source\",\n    \"importance\": \"high\",\n    \"name\": \"source\",\n    \"type\": \"text\",\n    \"description\": \"URI to external document, or path to document found inside H5P (under /content)\"\n  },\n  {\n    \"name\": \"resizeSupported\",\n    \"type\": \"boolean\",\n    \"label\": \"Resize supported\",\n    \"importance\": \"medium\",\n    \"description\": \"If enabled, fullscreen button will be displayed, and H5P will be resized to fit its surroundings\",\n    \"default\": true\n  }\n]\n', NULL, NULL, NULL, NULL, NULL, 'https://h5p.org/iframe-embedder', 1),
(45, 'H5P.FreeTextQuestion', 'Free Text Question', 1, 0, 16, 0, 0, '', 'h5p-free-text-question.js', 'h5p-free-text-question.css', '', '[\n  {\n    \"label\": \"Question\",\n    \"name\": \"question\",\n    \"type\": \"text\",\n    \"importance\": \"high\"\n  },\n  {\n    \"label\": \"Placeholder text\",\n    \"name\": \"placeholder\",\n    \"type\": \"text\",\n    \"importance\": \"high\",\n    \"default\": \"Enter your response here\",\n    \"description\": \"Text that initially will be shown in the input field. Will be removed automatically when the user starts writing.\"\n  },\n  {\n    \"label\": \"Max score\",\n    \"name\": \"maxScore\",\n    \"type\": \"number\",\n    \"importance\": \"high\",\n    \"description\": \"Used for grading and not shown to the learner\",\n    \"default\": 1\n  },\n  {\n    \"label\": \"Required\",\n    \"name\": \"isRequired\",\n    \"type\": \"boolean\",\n    \"importance\": \"high\",\n    \"description\": \"Learners must provide an answer in order to proceed\"\n  },\n  {\n    \"label\": \"Localize Free Text Question buttons\",\n    \"name\": \"i10n\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"collapsed\": true,\n    \"importance\": \"low\",\n    \"fields\": [\n      {\n        \"label\": \"Required text label\",\n        \"name\": \"requiredText\",\n        \"type\": \"text\",\n        \"description\": \"Text shown to notify learner that input is required before proceeding\",\n        \"default\": \"required\",\n        \"importance\": \"low\"\n      },\n      {\n        \"label\": \"Required message\",\n        \"name\": \"requiredMessage\",\n        \"type\": \"text\",\n        \"importance\": \"low\",\n        \"default\": \"This question requires an answer\",\n        \"description\": \"Will display if this field is unanswered and required by a wrapper content type\"\n      },\n      {\n        \"label\": \"Skip button label\",\n        \"name\": \"skipButtonLabel\",\n        \"type\": \"text\",\n        \"default\": \"Skip Question\",\n        \"importance\": \"low\"\n      },\n      {\n        \"label\": \"Proceed button label\",\n        \"name\": \"submitButtonLabel\",\n        \"type\": \"text\",\n        \"default\": \"Answer and proceed\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"language\",\n        \"type\": \"select\",\n        \"label\": \"Wysiwyg editor language\",\n        \"importance\": \"medium\",\n        \"description\": \"The language of the wysiwyg user interface\",\n        \"options\": [\n          {\n            \"value\": \"af\",\n            \"label\": \"Afrikaans\"\n          },\n          {\n            \"value\": \"ar\",\n            \"label\": \"Arabic\"\n          },\n          {\n            \"value\": \"az\",\n            \"label\": \"Azerbaijani\"\n          },\n          {\n            \"value\": \"bg\",\n            \"label\": \"Bulgarian\"\n          },\n          {\n            \"value\": \"bn\",\n            \"label\": \"Bengali\"\n          },\n          {\n            \"value\": \"bs\",\n            \"label\": \"Bosnian\"\n          },\n          {\n            \"value\": \"ca\",\n            \"label\": \"Catalan\"\n          },\n          {\n            \"value\": \"cs\",\n            \"label\": \"Czech\"\n          },\n          {\n            \"value\": \"cy\",\n            \"label\": \"Welsh\"\n          },\n          {\n            \"value\": \"da\",\n            \"label\": \"Danish\"\n          },\n          {\n            \"value\": \"de-ch\",\n            \"label\": \"German (Switzerland)\"\n          },\n          {\n            \"value\": \"de\",\n            \"label\": \"German\"\n          },\n          {\n            \"value\": \"el\",\n            \"label\": \"Greek\"\n          },\n          {\n            \"value\": \"en-au\",\n            \"label\": \"English (Australia)\"\n          },\n          {\n            \"value\": \"en-ca\",\n            \"label\": \"English (Canada)\"\n          },\n          {\n            \"value\": \"en-gb\",\n            \"label\": \"English (United Kingdom)\"\n          },\n          {\n            \"value\": \"en\",\n            \"label\": \"English\"\n          },\n          {\n            \"value\": \"eo\",\n            \"label\": \"Esperanto\"\n          },\n          {\n            \"value\": \"es-mx\",\n            \"label\": \"Spanish (Mexico)\"\n          },\n          {\n            \"value\": \"es\",\n            \"label\": \"Spanish (Spain)\"\n          },\n          {\n            \"value\": \"et\",\n            \"label\": \"Estonian\"\n          },\n          {\n            \"value\": \"eu\",\n            \"label\": \"Basque\"\n          },\n          {\n            \"value\": \"fa\",\n            \"label\": \"Farsi\"\n          },\n          {\n            \"value\": \"fi\",\n            \"label\": \"Finnish\"\n          },\n          {\n            \"value\": \"fo\",\n            \"label\": \"Faeroese\"\n          },\n          {\n            \"value\": \"fr-ca\",\n            \"label\": \"French (Canada)\"\n          },\n          {\n            \"value\": \"fr\",\n            \"label\": \"French (Standard)\"\n          },\n          {\n            \"value\": \"gl\",\n            \"label\": \"Galician\"\n          },\n          {\n            \"value\": \"gu\",\n            \"label\": \"Gujarati\"\n          },\n          {\n            \"value\": \"he\",\n            \"label\": \"Hebrew (modern)\"\n          },\n          {\n            \"value\": \"hi\",\n            \"label\": \"Hindi\"\n          },\n          {\n            \"value\": \"hr\",\n            \"label\": \"Croatian\"\n          },\n          {\n            \"value\": \"hu\",\n            \"label\": \"Hungarian\"\n          },\n          {\n            \"value\": \"id\",\n            \"label\": \"Indonesian\"\n          },\n          {\n            \"value\": \"is\",\n            \"label\": \"Icelandic\"\n          },\n          {\n            \"value\": \"it\",\n            \"label\": \"Italian (Standard)\"\n          },\n          {\n            \"value\": \"ja\",\n            \"label\": \"Japanese\"\n          },\n          {\n            \"value\": \"ka\",\n            \"label\": \"Georgian\"\n          },\n          {\n            \"value\": \"km\",\n            \"label\": \"Central Khmer\"\n          },\n          {\n            \"value\": \"ko\",\n            \"label\": \"Korean\"\n          },\n          {\n            \"value\": \"ku\",\n            \"label\": \"Kurdish\"\n          },\n          {\n            \"value\": \"lt\",\n            \"label\": \"Lithuanian\"\n          },\n          {\n            \"value\": \"lv\",\n            \"label\": \"Latvian\"\n          },\n          {\n            \"value\": \"mk\",\n            \"label\": \"Macedonian\"\n          },\n          {\n            \"value\": \"mn\",\n            \"label\": \"Mongolian\"\n          },\n          {\n            \"value\": \"ms\",\n            \"label\": \"Malay\"\n          },\n          {\n            \"value\": \"nb\",\n            \"label\": \"Norwegian Bokmål\"\n          },\n          {\n            \"value\": \"nl\",\n            \"label\": \"Dutch (Standard)\"\n          },\n          {\n            \"value\": \"no\",\n            \"label\": \"Norwegian\"\n          },\n          {\n            \"value\": \"oc\",\n            \"label\": \"Occitan\"\n          },\n          {\n            \"value\": \"pl\",\n            \"label\": \"Polish\"\n          },\n          {\n            \"value\": \"pt-br\",\n            \"label\": \"Portuguese (Brazil)\"\n          },\n          {\n            \"value\": \"pt\",\n            \"label\": \"Portuguese (Portugal)\"\n          },\n          {\n            \"value\": \"ro\",\n            \"label\": \"Romanian\"\n          },\n          {\n            \"value\": \"ru\",\n            \"label\": \"Russian\"\n          },\n          {\n            \"value\": \"si\",\n            \"label\": \"Sinhala/Sinhalese\"\n          },\n          {\n            \"value\": \"sk\",\n            \"label\": \"Slovak\"\n          },\n          {\n            \"value\": \"sl\",\n            \"label\": \"Slovenian\"\n          },\n          {\n            \"value\": \"sq\",\n            \"label\": \"Albanian\"\n          },\n          {\n            \"value\": \"sr-latn\",\n            \"label\": \"Serbian (Latin)\"\n          },\n          {\n            \"value\": \"sr\",\n            \"label\": \"Serbian\"\n          },\n          {\n            \"value\": \"sv\",\n            \"label\": \"Swedish\"\n          },\n          {\n            \"value\": \"th\",\n            \"label\": \"Thai\"\n          },\n          {\n            \"value\": \"tr\",\n            \"label\": \"Turkish\"\n          },\n          {\n            \"value\": \"tt\",\n            \"label\": \"Tatar\"\n          },\n          {\n            \"value\": \"ug\",\n            \"label\": \"Uighur/Uyghur\"\n          },\n          {\n            \"value\": \"uk\",\n            \"label\": \"Ukrainian\"\n          },\n          {\n            \"value\": \"vi\",\n            \"label\": \"Vietnamese\"\n          },\n          {\n            \"value\": \"zh-cn\",\n            \"label\": \"Chinese (PRC)\"\n          }\n        ],\n        \"default\": \"en\"\n      }\n    ]\n  }\n]\n', NULL, 1, 13, NULL, NULL, NULL, 1),
(46, 'H5P.GoToQuestion', 'Crossroads', 1, 3, 15, 0, 0, '', 'scripts/go-to-question.js', 'styles/go-to-question.css', '', '[\n  {\n    \"name\": \"text\",\n    \"type\": \"text\",\n    \"label\": \"Question Text\",\n    \"importance\": \"high\",\n    \"description\": \"The question that the user will make a choice based upon.\"\n  },\n  {\n    \"name\": \"choices\",\n    \"type\": \"list\",\n    \"label\": \"Choices\",\n    \"importance\": \"high\",\n    \"entity\": \"choice\",\n    \"min\": 2,\n    \"field\": {\n      \"name\": \"choice\",\n      \"type\": \"group\",\n      \"fields\": [\n        {\n          \"name\": \"text\",\n          \"type\": \"text\",\n          \"label\": \"Choice Text\",\n          \"importance\": \"high\",\n          \"description\": \"The label that will displayed on the choice button.\"\n        },\n        {\n          \"name\": \"goTo\",\n          \"type\": \"number\",\n          \"widget\": \"timecode\",\n          \"label\": \"Go To\",\n          \"importance\": \"high\",\n          \"description\": \"The target time the user will be taken to upon pressing the choice button. Enter timecode in the format M:SS.\"\n        },\n        {\n          \"name\": \"ifChosenText\",\n          \"type\": \"text\",\n          \"optional\": true,\n          \"label\": \"If Chosen Text\",\n          \"importance\": \"low\",\n          \"description\": \"An optional confirmation text that will be displayed after the user has pressed the choice button.\"\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"continueButtonLabel\",\n    \"type\": \"text\",\n    \"label\": \"Continue Button Label\",\n    \"importance\": \"low\",\n    \"default\": \"Continue\",\n    \"common\": true\n  }\n]', NULL, 1, 6, '{\"disable\":true,\"disableExtraTitleField\":true}', NULL, NULL, 1),
(47, 'H5P.GuidedTour', 'Guided tour', 1, 0, 6, 0, 0, '', 'scripts/h5p-guided-tour.js', 'styles/h5p-guided-tour.css', '', '', NULL, NULL, NULL, NULL, NULL, NULL, 1);
INSERT INTO `mdl_h5p_libraries` (`id`, `machinename`, `title`, `majorversion`, `minorversion`, `patchversion`, `runnable`, `fullscreen`, `embedtypes`, `preloadedjs`, `preloadedcss`, `droplibrarycss`, `semantics`, `addto`, `coremajor`, `coreminor`, `metadatasettings`, `tutorial`, `example`, `enabled`) VALUES
(48, 'H5P.InteractiveVideo', 'Interactive Video', 1, 27, 9, 1, 1, 'iframe', 'dist/h5p-interactive-video.js', 'dist/h5p-interactive-video.css', '', '[\n  {\n    \"name\": \"interactiveVideo\",\n    \"type\": \"group\",\n    \"widget\": \"wizard\",\n    \"label\": \"Interactive Video Editor\",\n    \"importance\": \"high\",\n    \"fields\": [\n      {\n        \"name\": \"video\",\n        \"type\": \"group\",\n        \"label\": \"Upload/embed video\",\n        \"importance\": \"high\",\n        \"fields\": [\n          {\n            \"name\": \"files\",\n            \"type\": \"video\",\n            \"label\": \"Add a video\",\n            \"importance\": \"high\",\n            \"description\": \"Click below to add a video you wish to use in your interactive video. You can add a video link or upload video files. It is possible to add several versions of the video with different qualities. To ensure maximum support in browsers at least add a version in webm and mp4 formats.\",\n            \"extraAttributes\": [\n              \"metadata\"\n            ],\n            \"enableCustomQualityLabel\": true\n          },\n          {\n            \"name\": \"startScreenOptions\",\n            \"type\": \"group\",\n            \"label\": \"Start screen options (unsupported for YouTube videos)\",\n            \"importance\": \"low\",\n            \"fields\": [\n              {\n                \"name\": \"title\",\n                \"type\": \"text\",\n                \"label\": \"The title of this interactive video\",\n                \"importance\": \"low\",\n                \"maxLength\": 60,\n                \"default\": \"Interactive Video\",\n                \"description\": \"Used in summaries, statistics etc.\"\n              },\n              {\n                \"name\": \"hideStartTitle\",\n                \"type\": \"boolean\",\n                \"label\": \"Hide title on video start screen\",\n                \"importance\": \"low\",\n                \"optional\": true,\n                \"default\": false\n              },\n              {\n                \"name\": \"shortStartDescription\",\n                \"type\": \"text\",\n                \"label\": \"Short description (Optional)\",\n                \"importance\": \"low\",\n                \"optional\": true,\n                \"maxLength\": 120,\n                \"description\": \"Optional. Display a short description text on the video start screen. Does not work for YouTube videos.\"\n              },\n              {\n                \"name\": \"poster\",\n                \"type\": \"image\",\n                \"label\": \"Poster image\",\n                \"importance\": \"low\",\n                \"optional\": true,\n                \"description\": \"Image displayed before the user launches the video. Does not work for YouTube Videos.\"\n              }\n            ]\n          },\n          {\n            \"name\": \"textTracks\",\n            \"type\": \"group\",\n            \"label\": \"Text tracks (unsupported for YouTube videos)\",\n            \"importance\": \"low\",\n            \"fields\": [\n              {\n                \"name\": \"videoTrack\",\n                \"type\": \"list\",\n                \"label\": \"Available text tracks\",\n                \"importance\": \"low\",\n                \"optional\": true,\n                \"entity\": \"Track\",\n                \"min\": 0,\n                \"defaultNum\": 1,\n                \"field\": {\n                  \"name\": \"track\",\n                  \"type\": \"group\",\n                  \"label\": \"Track\",\n                  \"importance\": \"low\",\n                  \"expanded\": false,\n                  \"fields\": [\n                    {\n                      \"name\": \"label\",\n                      \"type\": \"text\",\n                      \"label\": \"Track label\",\n                      \"description\": \"Used if you offer multiple tracks and the user has to choose a track. For instance \'Spanish subtitles\' could be the label of a Spanish subtitle track.\",\n                      \"importance\": \"low\",\n                      \"default\": \"Subtitles\",\n                      \"optional\": true\n                    },\n                    {\n                      \"name\": \"kind\",\n                      \"type\": \"select\",\n                      \"label\": \"Type of text track\",\n                      \"importance\": \"low\",\n                      \"default\": \"subtitles\",\n                      \"options\": [\n                        {\n                          \"value\": \"subtitles\",\n                          \"label\": \"Subtitles\"\n                        },\n                        {\n                          \"value\": \"captions\",\n                          \"label\": \"Captions\"\n                        },\n                        {\n                          \"value\": \"descriptions\",\n                          \"label\": \"Descriptions\"\n                        }\n                      ]\n                    },\n                    {\n                      \"name\": \"srcLang\",\n                      \"type\": \"text\",\n                      \"label\": \"Source language, must be defined for subtitles\",\n                      \"importance\": \"low\",\n                      \"default\": \"en\",\n                      \"description\": \"Must be a valid BCP 47 language tag. If \'Subtitles\' is the type of text track selected, the source language of the track must be defined.\"\n                    },\n                    {\n                      \"name\": \"track\",\n                      \"type\": \"file\",\n                      \"label\": \"Track source (WebVTT file)\",\n                      \"importance\": \"low\"\n                    }\n                  ]\n                }\n              },\n              {\n                \"name\": \"defaultTrackLabel\",\n                \"type\": \"text\",\n                \"label\": \"Default text track\",\n                \"description\": \"If left empty or not matching any of the text tracks the first text track will be used as the default.\",\n                \"importance\": \"low\",\n                \"optional\": true\n              }\n            ]\n          }\n        ]\n      },\n      {\n        \"name\": \"assets\",\n        \"type\": \"group\",\n        \"label\": \"Add interactions\",\n        \"importance\": \"high\",\n        \"widget\": \"interactiveVideo\",\n        \"video\": \"video/files\",\n        \"poster\": \"video/startScreenOptions/poster\",\n        \"fields\": [\n          {\n            \"name\": \"interactions\",\n            \"type\": \"list\",\n            \"field\": {\n              \"name\": \"interaction\",\n              \"type\": \"group\",\n              \"fields\": [\n                {\n                  \"name\": \"duration\",\n                  \"type\": \"group\",\n                  \"widget\": \"duration\",\n                  \"label\": \"Display time\",\n                  \"importance\": \"low\",\n                  \"fields\": [\n                    {\n                      \"name\": \"from\",\n                      \"type\": \"number\"\n                    },\n                    {\n                      \"name\": \"to\",\n                      \"type\": \"number\"\n                    }\n                  ]\n                },\n                {\n                  \"name\": \"pause\",\n                  \"label\": \"Pause video\",\n                  \"importance\": \"low\",\n                  \"type\": \"boolean\"\n                },\n                {\n                  \"name\": \"displayType\",\n                  \"label\": \"Display as\",\n                  \"importance\": \"low\",\n                  \"description\": \"<b>Button</b> is a collapsed interaction the user must press to open. <b>Poster</b> is an expanded interaction displayed directly on top of the video\",\n                  \"type\": \"select\",\n                  \"widget\": \"imageRadioButtonGroup\",\n                  \"options\": [\n                    {\n                      \"value\": \"button\",\n                      \"label\": \"Button\"\n                    },\n                    {\n                      \"value\": \"poster\",\n                      \"label\": \"Poster\"\n                    }\n                  ],\n                  \"default\": \"button\"\n                },\n                {\n                  \"name\": \"buttonOnMobile\",\n                  \"label\": \"Turn into button on small screens\",\n                  \"importance\": \"low\",\n                  \"type\": \"boolean\",\n                  \"default\": false\n                },\n                {\n                  \"name\": \"label\",\n                  \"type\": \"text\",\n                  \"widget\": \"html\",\n                  \"label\": \"Label\",\n                  \"importance\": \"low\",\n                  \"description\": \"Label displayed next to interaction icon.\",\n                  \"optional\": true,\n                  \"enterMode\": \"p\",\n                  \"tags\": [\n                    \"p\"\n                  ]\n                },\n                {\n                  \"name\": \"x\",\n                  \"type\": \"number\",\n                  \"importance\": \"low\",\n                  \"widget\": \"none\"\n                },\n                {\n                  \"name\": \"y\",\n                  \"type\": \"number\",\n                  \"importance\": \"low\",\n                  \"widget\": \"none\"\n                },\n                {\n                  \"name\": \"width\",\n                  \"type\": \"number\",\n                  \"widget\": \"none\",\n                  \"importance\": \"low\",\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"height\",\n                  \"type\": \"number\",\n                  \"widget\": \"none\",\n                  \"importance\": \"low\",\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"libraryTitle\",\n                  \"type\": \"text\",\n                  \"importance\": \"low\",\n                  \"optional\": true,\n                  \"widget\": \"none\"\n                },\n                {\n                  \"name\": \"action\",\n                  \"type\": \"library\",\n                  \"importance\": \"low\",\n                  \"options\": [\n                    \"H5P.Nil 1.0\",\n                    \"H5P.Text 1.1\",\n                    \"H5P.Table 1.2\",\n                    \"H5P.Link 1.3\",\n                    \"H5P.Image 1.1\",\n                    \"H5P.Summary 1.10\",\n                    \"H5P.SingleChoiceSet 1.11\",\n                    \"H5P.MultiChoice 1.16\",\n                    \"H5P.TrueFalse 1.8\",\n                    \"H5P.Blanks 1.14\",\n                    \"H5P.DragQuestion 1.14\",\n                    \"H5P.MarkTheWords 1.11\",\n                    \"H5P.DragText 1.10\",\n                    \"H5P.GoToQuestion 1.3\",\n                    \"H5P.IVHotspot 1.2\",\n                    \"H5P.Questionnaire 1.3\",\n                    \"H5P.FreeTextQuestion 1.0\",\n                    \"H5P.MultiMediaChoice 0.3\"\n                  ]\n                },\n                {\n                  \"name\": \"adaptivity\",\n                  \"type\": \"group\",\n                  \"label\": \"Adaptivity\",\n                  \"importance\": \"low\",\n                  \"optional\": true,\n                  \"fields\": [\n                    {\n                      \"name\": \"correct\",\n                      \"type\": \"group\",\n                      \"label\": \"Action on all correct\",\n                      \"fields\": [\n                        {\n                          \"name\": \"seekTo\",\n                          \"type\": \"number\",\n                          \"widget\": \"timecode\",\n                          \"label\": \"Seek to\",\n                          \"description\": \"Enter timecode in the format M:SS\"\n                        },\n                        {\n                          \"name\": \"allowOptOut\",\n                          \"type\": \"boolean\",\n                          \"label\": \"Allow the user to opt out and continue\"\n                        },\n                        {\n                          \"name\": \"message\",\n                          \"type\": \"text\",\n                          \"widget\": \"html\",\n                          \"enterMode\": \"p\",\n                          \"tags\": [\n                            \"strong\",\n                            \"em\",\n                            \"del\",\n                            \"a\",\n                            \"code\"\n                          ],\n                          \"label\": \"Message\"\n                        },\n                        {\n                          \"name\": \"seekLabel\",\n                          \"type\": \"text\",\n                          \"label\": \"Label for seek button\"\n                        }\n                      ]\n                    },\n                    {\n                      \"name\": \"wrong\",\n                      \"type\": \"group\",\n                      \"label\": \"Action on wrong\",\n                      \"fields\": [\n                        {\n                          \"name\": \"seekTo\",\n                          \"type\": \"number\",\n                          \"widget\": \"timecode\",\n                          \"label\": \"Seek to\",\n                          \"description\": \"Enter timecode in the format M:SS\"\n                        },\n                        {\n                          \"name\": \"allowOptOut\",\n                          \"type\": \"boolean\",\n                          \"label\": \"Allow the user to opt out and continue\"\n                        },\n                        {\n                          \"name\": \"message\",\n                          \"type\": \"text\",\n                          \"widget\": \"html\",\n                          \"enterMode\": \"p\",\n                          \"tags\": [\n                            \"strong\",\n                            \"em\",\n                            \"del\",\n                            \"a\",\n                            \"code\"\n                          ],\n                          \"label\": \"Message\"\n                        },\n                        {\n                          \"name\": \"seekLabel\",\n                          \"type\": \"text\",\n                          \"label\": \"Label for seek button\"\n                        }\n                      ]\n                    },\n                    {\n                      \"name\": \"requireCompletion\",\n                      \"type\": \"boolean\",\n                      \"label\": \"Require full score for task before proceeding\",\n                      \"description\": \"For best functionality this option should be used in conjunction with the \\\"Disable navigation forward in a video\\\" option of Interactive Video.\"\n                    }\n                  ]\n                },\n                {\n                  \"name\": \"visuals\",\n                  \"label\": \"Visuals\",\n                  \"importance\": \"low\",\n                  \"type\": \"group\",\n                  \"fields\": [\n                    {\n                      \"name\": \"backgroundColor\",\n                      \"type\": \"text\",\n                      \"label\": \"Background color\",\n                      \"widget\": \"colorSelector\",\n                      \"default\": \"rgb(255, 255, 255)\",\n                      \"spectrum\": {\n                        \"showInput\": true,\n                        \"showAlph