(58, 'H5P.SimpleMultiChoice', 'Simple Multi Choice', 1, 1, 22, 0, 0, '', 'dist/dist.js', 'dist/styles.css', '', '[\n  {\n    \"name\": \"question\",\n    \"label\": \"Question\",\n    \"importance\": \"high\",\n    \"type\": \"text\"\n  },\n  {\n    \"name\": \"inputType\",\n    \"label\": \"Multiple choice type\",\n    \"importance\": \"high\",\n    \"type\": \"select\",\n    \"options\": [\n      {\n        \"label\": \"Multiple answers\",\n        \"value\": \"checkbox\"\n      },\n      {\n        \"label\": \"Single answer\",\n        \"value\": \"radio\"\n      }\n    ],\n    \"default\": \"checkbox\"\n  },\n  {\n    \"name\": \"alternatives\",\n    \"label\": \"Answer alternatives\",\n    \"type\": \"list\",\n    \"importance\": \"high\",\n    \"entity\": \"Alternative\",\n    \"min\": 2,\n    \"field\": {\n      \"type\": \"group\",\n      \"name\": \"alternative\",\n      \"label\": \"Alternative\",\n      \"fields\": [\n        {\n          \"name\": \"text\",\n          \"label\": \"Text\",\n          \"importance\": \"high\",\n          \"type\": \"text\"\n        },\n        {\n          \"name\": \"feedback\",\n          \"type\": \"group\",\n          \"label\": \"Feedback\",\n          \"importance\": \"low\",\n          \"optional\": true,\n          \"fields\": [\n            {\n              \"name\": \"chosenFeedback\",\n              \"type\": \"text\",\n              \"widget\": \"html\",\n              \"label\": \"Message displayed if answer is selected\",\n              \"importance\": \"low\",\n              \"description\": \"Message will appear below the answer on \\\"continue\\\" if this answer is selected.\",\n              \"optional\": true,\n              \"tags\": [\n                \"strong\",\n                \"em\",\n                \"sub\",\n                \"sup\",\n                \"a\",\n                \"code\"\n              ]\n            },\n            {\n              \"name\": \"notChosenFeedback\",\n              \"type\": \"text\",\n              \"widget\": \"html\",\n              \"label\": \"Message displayed if answer is not selected\",\n              \"importance\": \"low\",\n              \"description\": \"Message will appear below the answer on \\\"continue\\\" if this answer is not selected.\",\n              \"optional\": true,\n              \"tags\": [\n                \"strong\",\n                \"em\",\n                \"sub\",\n                \"sup\",\n                \"a\",\n                \"code\"\n              ]\n            }\n          ]\n        }\n      ]\n    }\n  }\n]\n', NULL, NULL, NULL, NULL, NULL, NULL, 1),
(59, 'H5P.SingleChoiceSet', 'Single Choice Set', 1, 11, 44, 1, 0, 'iframe', 'scripts/stop-watch.js, scripts/sound-effects.js, scripts/xapi-event-builder.js, scripts/result-slide.js, scripts/solution-view.js, scripts/single-choice-alternative.js, scripts/single-choice.js, scripts/single-choice-set.js', 'styles/single-choice-set.css', '', '[\n  {\n    \"name\": \"choices\",\n    \"type\": \"list\",\n    \"label\": \"List of questions\",\n    \"importance\": \"high\",\n    \"entity\": \"question\",\n    \"min\": 1,\n    \"defaultNum\": 2,\n    \"widgets\": [\n      {\n        \"name\": \"ListEditor\",\n        \"label\": \"Default\"\n      },\n      {\n        \"name\": \"SingleChoiceSetTextualEditor\",\n        \"label\": \"Textual\"\n      }\n    ],\n    \"field\": {\n      \"name\": \"choice\",\n      \"type\": \"group\",\n      \"isSubContent\": true,\n      \"label\": \"Question & alternatives\",\n      \"importance\": \"high\",\n      \"fields\": [\n        {\n          \"name\": \"question\",\n          \"type\": \"text\",\n          \"widget\": \"html\",\n          \"tags\": [\n            \"p\",\n            \"br\",\n            \"strong\",\n            \"em\",\n            \"code\"\n          ],\n          \"label\": \"Question\",\n          \"importance\": \"high\"\n        },\n        {\n          \"name\": \"answers\",\n          \"type\": \"list\",\n          \"label\": \"Alternatives - first alternative is the correct one.\",\n          \"importance\": \"medium\",\n          \"entity\": \"answer\",\n          \"min\": 2,\n          \"max\": 4,\n          \"defaultNum\": 2,\n          \"field\": {\n            \"name\": \"answer\",\n            \"type\": \"text\",\n            \"widget\": \"html\",\n            \"tags\": [\n              \"p\",\n              \"br\",\n              \"strong\",\n              \"em\",\n              \"code\"\n            ],\n            \"label\": \"Alternative\",\n            \"importance\": \"medium\"\n          }\n      