(74, 'H5P.MemoryGame', 'Memory Game', 1, 3, 29, 1, 0, '', 'memory-game.js, card.js, counter.js, popup.js, timer.js, aria-live-region.js', 'memory-game.css', '', '[\n  {\n    \"name\": \"cards\",\n    \"type\": \"list\",\n    \"widgets\": [\n      {\n        \"name\": \"VerticalTabs\",\n        \"label\": \"Default\"\n      }\n    ],\n    \"label\": \"Cards\",\n    \"importance\": \"high\",\n    \"entity\": \"card\",\n    \"min\": 2,\n    \"max\": 100,\n    \"field\": {\n      \"type\": \"group\",\n      \"name\": \"card\",\n      \"label\": \"Card\",\n      \"importance\": \"high\",\n      \"fields\": [\n        {\n          \"name\": \"image\",\n          \"type\": \"image\",\n          \"label\": \"Image\",\n          \"importance\": \"high\",\n          \"ratio\": 1\n        },\n        {\n          \"name\": \"imageAlt\",\n          \"type\": \"text\",\n          \"label\": \"Alternative text for Image\",\n          \"importance\": \"high\",\n          \"description\": \"Describe what can be seen in the photo. The text is read by text-to-speech tools needed by visually impaired users.\"\n        },\n        {\n          \"name\": \"audio\",\n          \"type\": \"audio\",\n          \"importance\": \"high\",\n          \"label\": \"Audio Track\",\n          \"description\": \"An optional sound that plays when the card is turned.\",\n          \"optional\": true,\n          \"widgetExtensions\": [\n            \"AudioRecorder\"\n          ]\n        },\n        {\n          \"name\": \"match\",\n          \"type\": \"image\",\n          \"label\": \"Matching Image\",\n          \"importance\": \"low\",\n          \"optional\": true,\n          \"description\": \"An optional image to match against instead of using two cards with the same image.\",\n          \"ratio\": 1\n        },\n        {\n          \"name\": \"matchAlt\",\n          \"type\": \"text\",\n          \"label\": \"Alternative text for Matching Image\",\n          \"importance\": \"low\",\n          \"optional\": true,\n          \"description\": \"Describe what can be seen in the photo. The text is read by text-to-speech tools needed by visually impaired users.\"\n        },\n        {\n          \"name\": \"matchAudio\",\n          \"type\": \"audio\",\n          \"importance\": \"low\",\n          \"label\": \"Matching Audio Track\",\n          \"description\": \"An optional sound that plays when the second card is turned.\",\n          \"optional\": true,\n          \"widgetExtensions\": [\n            \"AudioRecorder\"\n          ]\n        },\n        {\n          \"name\": \"description\",\n          \"type\": \"text\",\n          \"label\": \"Description\",\n          \"importance\": \"low\",\n          \"maxLength\": 150,\n          \"optional\": true,\n          \"description\": \"An optional short text that will pop up once the two matching cards are found.\"\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you control how the game behaves.\",\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"name\": \"useGrid\",\n        \"type\": \"boolean\",\n        \"label\": \"Position the cards in a square\",\n        \"description\": \"Will try to match the number of columns and rows when laying out the cards. Afterward, the cards will be scaled to fit the container.\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"numCardsToUse\",\n        \"type\": \"number\",\n        \"label\": \"Number of cards to use\",\n        \"description\": \"Setting this to a number greater than 2 will make the game pick random cards from the list of cards.\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"min\": 2\n      },\n      {\n        \"name\": \"allowRetry\",\n        \"type\": \"boolean\",\n        \"label\": \"Add button for retrying when the game is over\",\n        \"importance\": \"low\",\n        \"default\": true\n      }\n    ]\n  },\n  {\n    \"name\": \"lookNFeel\",\n    \"type\": \"group\",\n    \"label\": \"Look and feel\",\n    \"importance\": \"low\",\n    \"description\": \"Control the visuals of the game.\",\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"name\": \"themeColor\",\n        \"type\": \"text\",\n        \"label\": \"Theme Color\",\n        \"importance\": \"low\",\n        \"description\": \"Choose a color to create a theme for your card game.\",\n        \"optional\": true,\n        \"default\": \"#707070\",\n        \"widget\": \"colorSelector\",\n        \"spectrum\": {\n          \"showInput\": true\n        }\n      },\n      {\n        \"name\": \"cardBack\",\n        \"type\": \"image\",\n        \"label\": \"Card Back\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"description\": \"Use a custom back for your cards.\",\n        \"ratio\": 1\n      }\n    ]\n  },\n  {\n    \"label\": \"Localization\",\n    \"importance\": \"low\",\n    \"name\": \"l10n\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"label\": \"Card turns text\",\n        \"importance\": \"low\",\n        \"name\": \"cardTurns\",\n        \"type\": \"text\",\n        \"default\": \"Card turns\"\n      },\n      {\n        \"label\": \"Time spent text\",\n        \"importance\": \"low\",\n        \"name\": \"timeSpent\",\n        \"type\": \"text\",\n        \"default\": \"Time spent\"\n      },\n      {\n        \"label\": \"Feedback text\",\n        \"importance\": \"low\",\n        \"name\": \"feedback\",\n        \"type\": \"text\",\n        \"default\": \"Good work!\"\n      },\n      {\n        \"label\": \"Try again button text\",\n        \"importance\": \"low\",\n        \"name\": \"tryAgain\",\n        \"type\": \"text\",\n        \"default\": \"Reset\"\n      },\n      {\n        \"label\": \"Close button label\",\n        \"importance\": \"low\",\n        \"name\": \"closeLabel\",\n        \"type\": \"text\",\n        \"default\": \"Close\"\n      },\n      {\n        \"label\": \"Game label\",\n        \"importance\": \"low\",\n        \"name\": \"label\",\n        \"type\": \"text\",\n        \"default\": \"Memory Game. Find the matching cards.\"\n      },\n      {\n        \"label\": \"Game instructions\",\n        \"importance\": \"low\",\n        \"name\": \"label\",\n        \"type\": \"text\",\n        \"default\": \"Use arrow keys left and right to navigate cards. Use space or enter key to turn card.\"\n      },\n      {\n        \"label\": \"Game finished label\",\n        \"importance\": \"low\",\n        \"name\": \"done\",\n        \"type\": \"text\",\n        \"default\": \"All of the cards have been found.\"\n      },\n      {\n        \"label\": \"Card indexing label\",\n        \"description\": \"%num and %total are placeholders and will be replaced with the respective values for the card.\",\n        \"importance\": \"low\",\n        \"name\": \"cardPrefix\",\n        \"type\": \"text\",\n        \"default\": \"Card %num of %total:\"\n      },\n      {\n        \"label\": \"Card unturned label\",\n        \"importance\": \"low\",\n        \"name\": \"cardUnturned\",\n        \"type\": \"text\",\n        \"default\": \"Unturned. Click to turn.\"\n      },\n      {\n        \"label\": \"Card turned label\",\n        \"importance\": \"low\",\n        \"name\": \"cardTurned\",\n        \"type\": \"text\",\n        \"default\": \"Turned.\"\n      },\n      {\n        \"label\": \"Card matched label\",\n        \"importance\": \"low\",\n        \"name\": \"cardMatched\",\n        \"type\": \"text\",\n        \"default\": \"Match found.\"\n      },\n      {\n        \"label\": \"Card matched announcement\",\n        \"importance\": \"low\",\n        \"name\": \"cardMatchedA11y\",\n        \"type\": \"text\",\n        \"default\": \"Your cards match!\"\n      },\n      {\n        \"label\": \"Card not matched announcement\",\n        \"importance\": \"low\",\n        \"name\": \"cardNotMatchedA11y\",\n        \"type\": \"text\",\n        \"default\": \"Your chosen cards do not match. Turn other cards to try again.\"\n      }\n    ]\n  }\n]\n', NULL, NULL, NULL, NULL, 'https://h5p.org/documentation/content-author-guide/tutorials-for-authors/memory-game', 'https://h5p.org/memory-game', 1),
