(81, 'H5P.Timeline', 'Timeline', 1, 1, 25, 1, 1, 'iframe', 'timeline.js', 'timeline.css', '', '[\n  {\n    \"name\": \"timeline\",\n    \"label\": \"Timeline\",\n    \"importance\": \"high\",\n    \"type\": \"group\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"headline\",\n        \"type\": \"text\",\n        \"label\": \"Headline\",\n        \"importance\": \"high\",\n        \"description\": \"Main timeline heading goes here (first page)\"\n      },\n      {\n        \"name\": \"text\",\n        \"type\": \"text\",\n        \"label\": \"Body Text\",\n        \"importance\": \"medium\",\n        \"widget\": \"html\",\n        \"description\": \"The main timeline body goes here (first page).\",\n        \"optional\": true,\n        \"tags\": [\n          \"strong\",\n          \"em\",\n          \"del\",\n          \"a\",\n          \"ul\",\n          \"ol\",\n          \"hr\",\n          \"code\"\n        ]\n      },\n      {\n        \"name\": \"defaultZoomLevel\",\n        \"type\": \"text\",\n        \"label\": \"Default zoom level\",\n        \"importance\": \"low\",\n        \"default\": \"0\",\n        \"optional\": true,\n        \"description\": \"This will tweak the default zoom level. Equivilent to pressing the zoom in or zoom out button the specified number of times. Negative numbers zoom out. default is 0\"\n      },\n      {\n        \"name\": \"backgroundImage\",\n        \"type\": \"image\",\n        \"label\": \"Background image\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"description\": \"An image to display as background.\"\n      },\n      {\n        \"name\": \"height\",\n        \"type\": \"number\",\n        \"label\": \"Height\",\n        \"importance\": \"low\",\n        \"description\": \"The height in pixels\",\n        \"default\": 600\n      },\n      {\n        \"name\": \"asset\",\n        \"type\": \"group\",\n        \"label\": \"Asset\",\n        \"importance\": \"low\",