(93, 'H5P.Audio', 'Audio', 1, 2, 14, 1, 0, 'iframe', 'scripts/audio.js', 'styles/audio.css', '', '[\n  {\n    \"name\": \"files\",\n    \"type\": \"audio\",\n    \"importance\": \"high\",\n    \"label\": \"Source files\"\n  },\n  {\n    \"name\": \"playerMode\",\n    \"type\": \"select\",\n    \"importance\": \"low\",\n    \"label\": \"Player mode\",\n    \"description\": \"Select the layout of the player.\",\n    \"options\": [\n      {\n        \"value\": \"minimalistic\",\n        \"label\": \"Minimalistic\"\n      },\n      {\n        \"value\": \"full\",\n        \"label\": \"Full\"\n      },\n      {\n        \"value\": \"transparent\",\n        \"label\": \"Transparent\"\n      }\n    ],\n    \"default\": \"minimalistic\"\n  },\n  {\n    \"name\": \"fitToWrapper\",\n    \"type\": \"boolean\",\n    \"importance\": \"low\",\n    \"label\": \"Fit to wrapper\",\n    \"default\": false,\n    \"descriptions\": \"Adjust audioplayer size to use available space\"\n  },\n  {\n    \"name\": \"controls\",\n    \"type\": \"boolean\",\n    \"importance\": \"low\",\n    \"label\": \"Enable controls\",\n    \"default\": true,\n    \"description\": \"Controls allow the user to for instance pause the audio\"\n  },\n  {\n    \"name\": \"autoplay\",\n    \"type\": \"boolean\",\n    \"importance\": \"low\",\n    \"label\": \"Enable autoplay\",\n    \"description\": \"With autoplay the audio starts to play immediately. If autoplay is disabled the user presses a play button to start the audio.\"\n  },\n  {\n    \"name\": \"copyright\",\n    \"type\": \"group\",\n    \"importance\": \"low\",\n    \"label\": \"Copyright information\",\n    \"deprecated\": true,\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"name\": \"title\",\n        \"type\": \"text\",\n        \"label\": \"Title\",\n        \"placeholder\": \"Für Elise\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"author\",\n        \"type\": \"text\",\n        \"label\": \"Author\",\n        \"placeholder\": \"Ludwig van Beethoven\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"source\",\n        \"type\": \"text\",\n        \"label\": \"Source\",\n        \"placeholder\": \"http://en.wikipedia.org/wiki/F%C3%BCr_Elise\",\n        \"optional\": true,\n        \"regexp\": {\n          \"pattern\": \"^http[s]?://.+\",\n          \"modifiers\": \"i\"\n        }\n      },\n      {\n        \"name\": \"license\",\n        \"type\": \"select\",\n        \"label\": \"License\",\n        \"default\": \"U\",\n        \"options\": [\n          {\n            \"value\": \"U\",\n            \"label\": \"Undisclosed\"\n          },\n          {\n            \"value\": \"CC BY\",\n            \"label\": \"Attribution\"\n          },\n          {\n            \"value\": \"CC BY-SA\",\n            \"label\": \"Attribution-ShareAlike\"\n          },\n          {\n            \"value\": \"CC BY-ND\",\n            \"label\": \"Attribution-NoDerivs\"\n          },\n          {\n            \"value\": \"CC BY-NC\",\n            \"label\": \"Attribution-NonCommercial\"\n          },\n          {\n            \"value\": \"CC BY-NC-SA\",\n            \"label\": \"Attribution-NonCommercial-ShareAlike\"\n          },\n          {\n            \"value\": \"CC BY-NC-ND\",\n            \"label\": \"Attribution-NonCommercial-NoDerivs\"\n          },\n          {\n            \"value\": \"GNU GPL\",\n            \"label\": \"General Public License\"\n          },\n          {\n            \"value\": \"PD\",\n            \"label\": \"Public Domain\"\n          },\n          {\n            \"value\": \"ODC PDDL\",\n            \"label\": \"Public Domain Dedication and Licence\"\n          },\n          {\n            \"value\": \"CC PDM\",\n            \"label\": \"Public Domain Mark\"\n          },\n          {\n            \"value\": \"C\",\n            \"label\": \"Copyright\"\n          }\n        ]\n      }\n    ]\n  },\n  {\n    \"name\": \"contentName\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Audio content name\",\n    \"common\": true,\n    \"default\": \"Audio\"\n  },\n  {\n    \"name\": \"audioNotSupported\",\n    \"type\": \"text\",\n    \"label\": \"Audio not supported message\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Your browser does not support this audio\"\n  }\n]', NULL, 1, 4, NULL, NULL, NULL, 1),
(94, 'H5P.ImageSequencing', 'Image Sequencing', 1, 1, 0, 1, 0, 'iframe', 'scripts/h5p-image-sequencing.js, scripts/h5p-image-sequencing-card.js, scripts/h5p-image-sequencing-counter.js, scripts/h5p-image-sequencing-timer.js', 'styles/h5p-image-sequencing.css', '', '[\n  {\n    \"label\": \"Task Description\",\n    \"name\": \"taskDescription\",\n    \"type\": \"text\",\n    \"default\": \"Drag to arrange the images in the correct sequence\",\n    \"description\": \"A guide telling the user how to solve this task.\",\n    \"importance\": \"high\"\n  },\n  {\n    \"label\": \"Alternate Task Description\",\n    \"name\": \"altTaskDescription\",\n    \"type\": \"text\",\n    \"default\": \"Make the following list be ordered correctly. Use the cursor keys to navigate through the list items, use space to activate or deactivate an item and the cursor keys to move it\",\n    \"description\": \"A guide intended for visually impaired users on how to solve this task.\",\n    \"importance\": \"high\"\n  },\n  {\n    \"name\": \"sequenceImages\",\n    \"type\": \"list\",\n    \"widgets\": [\n      {\n        \"name\": \"VerticalTabs\",\n        \"label\": \"Default\"\n      }\n    ],\n    \"label\": \"Images\",\n    \"importance\": \"high\",\n    \"entity\": \"image\",\n    \"min\": 3,\n    \"field\": {\n      \"type\": \"group\",\n      \"name\": \"imageElement\",\n      \"label\": \"Image Element\",\n      \"importance\": \"high\",\n      \"fields\": [\n        {\n          \"name\": \"image\",\n          \"type\": \"image\",\n          \"label\": \"Image\",\n          \"importance\": \"high\"\n        },\n        {\n          \"name\": \"imageDescription\",\n          \"type\": \"text\",\n          \"label\": \"Image Description\",\n          \"importance\": \"low\",\n          \"description\": \"An image description for users who cannot recognize the image\"\n        },\n        {\n          \"name\": \"audio\",\n          \"description\": \"An optional audio for the card to play\",\n          \"type\": \"audio\",\n          \"label\": \"Audio files\",\n          \"importance\": \"low\",\n          \"optional\": true\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you control how the game behaves.\",\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"name\": \"enableSolution\",\n        \"type\": \"boolean\",\n        \"label\": \"Add a show solution button for the game\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableRetry\",\n        \"type\": \"boolean\",\n        \"label\": \"Add button for retrying when the game is over\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableResume\",\n        \"type\": \"boolean\",\n        \"label\": \"Add button for resuming from the current state \",\n        \"importance\": \"low\",\n        \"default\": true\n      }\n    ]\n  },\n  {\n    \"label\": \"Localization\",\n    \"importance\": \"low\",\n    \"name\": \"l10n\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"label\": \"Total Moves text\",\n        \"importance\": \"low\",\n        \"name\": \"totalMoves\",\n        \"type\": \"text\",\n        \"default\": \"Total Moves\"\n      },\n      {\n        \"label\": \"Time spent text\",\n        \"importance\": \"low\",\n        \"name\": \"timeSpent\",\n        \"type\": \"text\",\n        \"default\": \"Time spent\"\n      },\n      {\n        \"label\": \"Feedback text\",\n        \"importance\": \"low\",\n        \"name\": \"score\",\n        \"type\": \"text\",\n        \"default\": \"You got @score of @total points\",\n        \"description\": \"Feedback text, variables available: @score and @total. Example: \'You got @score of @total possible points\'\"\n      },\n      {\n        \"label\": \"Text for \\\"Check\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"checkAnswer\",\n        \"type\": \"text\",\n        \"default\": \"Check\"\n      },\n      {\n        \"label\": \"Text for \\\"Retry\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"tryAgain\",\n        \"type\": \"text\",\n        \"default\": \"Retry\"\n      },\n      {\n        \"label\": \"Text for \\\"Show Solution\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"showSolution\",\n        \"type\": \"text\",\n        \"default\": \"ShowSolution\"\n      },\n      {\n        \"label\": \"Text for \\\"Resume\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"resume\",\n        \"type\": \"text\",\n        \"default\": \"Resume\"\n      },\n      {\n        \"name\": \"audioNotSupported\",\n        \"type\": \"text\",\n        \"label\": \"Audio not supported message\",\n        \"importance\": \"low\",\n        \"common\": true,\n        \"default\": \"Audio Error\"\n      },\n      {\n        \"name\": \"ariaPlay\",\n        \"type\": \"text\",\n        \"label\": \"Play button (text for readspeakers)\",\n        \"importance\": \"low\",\n        \"common\": true,\n        \"default\": \"Play the corresponding audio\"\n      },\n      {\n        \"name\": \"ariaMoveDescription\",\n        \"type\": \"text\",\n        \"label\": \"Card moving description (text for readspeakers)\",\n        \"description\": \"@posSrc : card initial position, @posDes : card final position\",\n        \"importance\": \"low\",\n        \"common\": true,\n        \"default\": \"Moved @cardDesc from @posSrc to @posDes\"\n      },\n      {\n        \"name\": \"ariaCardDesc\",\n        \"type\": \"text\",\n        \"label\": \"Default Card Description (text for readspeakers)\",\n        \"importance\": \"low\",\n        \"common\": true,\n        \"default\": \"sequencing item\"\n      }\n    ]\n  }\n]\n', NULL, NULL, NULL, NULL, 'https://h5p.org/tutorial-image-sequencing', 'https://h5p.org/content-types/image-sequencing', 1),
(95, 'H5P.Flashcards', 'Flashcards', 1, 7, 10, 1, 0, 'iframe', 'js/xapi.js, js/flashcards.js', 'css/flashcards.css', '', '[\n  {\n    \"name\": \"description\",\n    \"type\": \"text\",\n    \"label\": \"Task description\",\n    \"importance\": \"high\"\n  },\n  {\n    \"name\": \"cards\",\n    \"type\": \"list\",\n    \"widgets\": [\n      {\n        \"name\": \"VerticalTabs\",\n        \"label\": \"Default\"\n      }\n    ],\n    \"label\": \"Cards\",\n    \"entity\": \"card\",\n    \"importance\": \"high\",\n    \"min\": 1,\n    \"defaultNum\": 1,\n    \"field\": {\n      \"name\": \"card\",\n      \"type\": \"group\",\n      \"label\": \"Card\",\n      \"importance\": \"high\",\n      \"fields\": [\n        {\n          \"name\": \"text\",\n          \"type\": \"text\",\n          \"label\": \"Question\",\n          \"importance\": \"high\",\n          \"optional\": true,\n          \"description\": \"Optional textual question for the card. (The card may use just an image, just a text or both)\"\n        },\n        {\n          \"name\": \"answer\",\n          \"type\": \"text\",\n          \"label\": \"Answer\",\n          \"importance\": \"high\",\n          \"optional\": true,\n          \"description\": \"Answer (solution) for the card. Use a forward slash / to split alternative solutions. Use \\\\/ if a solution should contain a /.\"\n        },\n        {\n          \"name\": \"image\",\n          \"type\": \"image\",\n          \"label\": \"Image\",\n          \"importance\": \"high\",\n          \"optional\": true,\n          \"description\": \"Optional image for the card. (The card may use just an image, just a text or both)\"\n        },\n        {\n          \"name\": \"imageAltText\",\n          \"type\": \"text\",\n          \"label\": \"Alternative text for image\",\n          \"importance\": \"high\",\n          \"optional\": true\n        },\n        {\n          \"name\": \"tip\",\n          \"type\": \"group\",\n          \"label\": \"Tip\",\n          \"importance\": \"low\",\n          \"optional\": true,\n          \"fields\": [\n            {\n              \"name\": \"tip\",\n              \"label\": \"Tip text\",\n              \"importance\": \"low\",\n              \"type\": \"text\",\n              \"widget\": \"html\",\n              \"tags\": [\n                \"p\",\n                \"br\",\n                \"strong\",\n                \"em\",\n                \"code\"\n              ],\n              \"optional\": true\n            }\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"label\": \"Progress text\",\n    \"name\": \"progressText\",\n    \"type\": \"text\",\n    \"default\": \"Card @card of @total\",\n    \"importance\": \"low\",\n    \"description\": \"Progress text, variables available: @card and @total. Example: \'Card @card of @total\'\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for the next button\",\n    \"name\": \"next\",\n    \"type\": \"text\",\n    \"default\": \"Next\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for the previous button\",\n    \"name\": \"previous\",\n    \"type\": \"text\",\n    \"default\": \"Previous\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for the check answers button\",\n    \"name\": \"checkAnswerText\",\n    \"type\": \"text\",\n    \"default\": \"Check\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Require user input before the solution can be viewed\",\n    \"name\": \"showSolutionsRequiresInput\",\n    \"type\": \"boolean\",\n    \"default\": true,\n    \"importance\": \"low\",\n    \"optional\": true\n  },\n  {\n    \"label\": \"Text for the answer input field\",\n    \"name\": \"defaultAnswerText\",\n    \"type\": \"text\",\n    \"default\": \"Your answer\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for correct answer\",\n    \"name\": \"correctAnswerText\",\n    \"type\": \"text\",\n    \"default\": \"Correct\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for incorrect answer\",\n    \"name\": \"incorrectAnswerText\",\n    \"type\": \"text\",\n    \"default\": \"Incorrect\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Show solution text\",\n    \"name\": \"showSolutionText\",\n    \"type\": \"text\",\n    \"default\": \"Correct answer(s)\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for results title\",\n    \"name\": \"results\",\n    \"type\": \"text\",\n    \"default\": \"Results\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for number of correct\",\n    \"name\": \"ofCorrect\",\n    \"type\": \"text\",\n    \"default\": \"@score of @total correct\",\n    \"importance\": \"low\",\n    \"description\": \"Result text, variables available: @score and @total. Example: \'@score of @total correct\'\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for show results\",\n    \"name\": \"showResults\",\n    \"type\": \"text\",\n    \"default\": \"Show results\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for short answer label\",\n    \"name\": \"answerShortText\",\n    \"type\": \"text\",\n    \"default\": \"A:\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for \\\"retry\\\" button\",\n    \"name\": \"retry\",\n    \"type\": \"text\",\n    \"default\": \"Retry\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Case sensitive\",\n    \"name\": \"caseSensitive\",\n    \"type\": \"boolean\",\n    \"default\": false,\n    \"description\": \"Makes sure the user input has to be exactly the same as the answer.\"\n  },\n  {\n    \"label\": \"Incorrect text for assistive technologies\",\n    \"name\": \"cardAnnouncement\",\n    \"type\": \"text\",\n    \"default\": \"Incorrect answer. Correct answer was @answer\",\n    \"description\": \"Text that will be announced to assistive technologies. Use @answer as variable.\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Correct feedback text for assistive technologies\",\n    \"name\": \"correctAnswerAnnouncement\",\n    \"type\": \"text\",\n    \"default\": \"@answer is correct.\",\n    \"description\": \"Text that will be announced to assistive technologies when a card is answered correctly. Use @answer as variable.\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Card change for assistive technologies\",\n    \"name\": \"pageAnnouncement\",\n    \"type\": \"text\",\n    \"default\": \"Page @current of @total\",\n    \"description\": \"Text that will be announced to assistive technologies when navigating between cards. Use @current and @total as variables.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"randomCards\",\n    \"type\": \"boolean\",\n    \"label\": \"Randomize cards\",\n    \"importance\": \"low\",\n    \"description\": \"Enable to randomize the order of cards on display.\",\n    \"default\": false\n  }\n]\n', NULL, 1, 4, NULL, 'https://h5p.org/tutorial-flashcards', 'https://h5p.org/flashcards', 1);
INSERT INTO `mdl_h5p_libraries` (`id`, `machinename`, `title`, `majorversion`, `minorversion`, `patchversion`, `runnable`, `fullscreen`, `embedtypes`, `preloadedjs`, `preloadedcss`, `droplibrarycss`, `semantics`, `addto`, `coremajor`, `coreminor`, `metadatasettings`, `tutorial`, `example`, `enabled`) VALUES
(96, 'H5P.SpeakTheWordsSet', 'Speak the Words Set', 1, 3, 4, 1, 0, 'iframe', 'dist/dist.js', '', '', '[\n  {\n    \"name\": \"introduction\",\n    \"label\": \"Introduction\",\n    \"type\": \"group\",\n    \"fields\": [\n      {\n        \"name\": \"showIntroPage\",\n        \"type\": \"boolean\",\n        \"optional\": true,\n        \"default\": false,\n        \"label\": \"Display introduction\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"introductionImage\",\n        \"type\": \"image\",\n        \"label\": \"Introduction image\",\n        \"optional\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"showIntroPage\",\n              \"equals\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"introductionImageAltText\",\n        \"type\": \"text\",\n        \"label\": \"Alternative text for introduction image\",\n        \"optional\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"showIntroPage\",\n              \"equals\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"introductionTitle\",\n        \"type\": \"text\",\n        \"label\": \"Title\",\n        \"optional\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"showIntroPage\",\n              \"equals\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"introductionText\",\n        \"type\": \"text\",\n        \"label\": \"Introduction text\",\n        \"optional\": true,\n        \"description\": \"This title will be displayed above the introduction text.\",\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"widget\": \"html\",\n          \"rules\": [\n            {\n              \"field\": \"showIntroPage\",\n              \"equals\": true\n            }\n          ]\n        },\n        \"tags\": [\n          \"sub\",\n          \"sup\",\n          \"strong\",\n          \"em\",\n          \"code\"\n        ]\n      }\n    ]\n  },\n  {\n    \"name\": \"questions\",\n    \"label\": \"Questions\",\n    \"importance\": \"high\",\n    \"type\": \"list\",\n    \"widgets\": [\n      {\n        \"name\": \"VerticalTabs\",\n        \"label\": \"Default\"\n      }\n    ],\n    \"min\": 1,\n    \"entity\": \"Question\",\n    \"field\": {\n      \"name\": \"question\",\n      \"type\": \"library\",\n      \"label\": \"Question\",\n      \"importance\": \"high\",\n      \"options\": [\n        \"H5P.SpeakTheWords 1.5\"\n      ]\n    }\n  },\n  {\n    \"name\": \"overallFeedback\",\n    \"type\": \"group\",\n    \"label\": \"Overall Feedback\",\n    \"importance\": \"low\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"overallFeedback\",\n        \"type\": \"list\",\n        \"widgets\": [\n          {\n            \"name\": \"RangeList\",\n            \"label\": \"Default\"\n          }\n        ],\n        \"importance\": \"high\",\n        \"label\": \"Define custom feedback for any score range\",\n        \"description\": \"Click the \\\"Add range\\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!\",\n        \"entity\": \"range\",\n        \"min\": 1,\n        \"defaultNum\": 1,\n        \"optional\": true,\n        \"field\": {\n          \"name\": \"overallFeedback\",\n          \"type\": \"group\",\n          \"importance\": \"low\",\n          \"fields\": [\n            {\n              \"name\": \"from\",\n              \"type\": \"number\",\n              \"label\": \"Score Range\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 0,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"to\",\n              \"type\": \"number\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 100,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"feedback\",\n              \"type\": \"text\",\n              \"label\": \"Feedback for defined score range\",\n              \"importance\": \"low\",\n              \"placeholder\": \"Fill in the feedback\",\n              \"optional\": true\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"l10n\",\n    \"type\": \"group\",\n    \"label\": \"Speak The Words Set labels and texts\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"name\": \"introductionButtonLabel\",\n        \"label\": \"Introduction button label\",\n        \"type\": \"text\",\n        \"default\": \"Start Course!\"\n      },\n      {\n        \"name\": \"solutionScreenResultsLabel\",\n        \"label\": \"Solution screen results label\",\n        \"type\": \"text\",\n        \"default\": \"Your results:\"\n      },\n      {\n        \"name\": \"showSolutionsButtonLabel\",\n        \"label\": \"Show solutions button label\",\n        \"type\": \"text\",\n        \"default\": \"Show solution\"\n      },\n      {\n        \"name\": \"retryButtonLabel\",\n        \"label\": \"Retry button label\",\n        \"type\": \"text\",\n        \"default\": \"Retry\"\n      },\n      {\n        \"name\": \"finishButtonLabel\",\n        \"label\": \"Finish button label\",\n        \"type\": \"text\",\n        \"default\": \"Finish\"\n      },\n      {\n        \"name\": \"nextQuestionAriaLabel\",\n        \"label\": \"Next question accessibility label\",\n        \"type\": \"text\",\n        \"default\": \"Next question\"\n      },\n      {\n        \"name\": \"previousQuestionAriaLabel\",\n        \"label\": \"Previous question accessibility label\",\n        \"type\": \"text\",\n        \"default\": \"Previous question\"\n      },\n      {\n        \"name\": \"navigationBarTitle\",\n        \"label\": \"Navigation bar title\",\n        \"description\": \"Titles for questions in navigation bar. \\\":num\\\" will be replaced with the actual slide number.\",\n        \"type\": \"text\",\n        \"default\": \"Slide :num\"\n      },\n      {\n        \"name\": \"answeredSlideAriaLabel\",\n        \"label\": \"Answered slide accessibility label\",\n        \"type\": \"text\",\n        \"default\": \"Answered\"\n      },\n      {\n        \"name\": \"activeSlideAriaLabel\",\n        \"label\": \"Active slide accessibility label\",\n        \"type\": \"text\",\n        \"default\": \"Currently active\"\n      }\n    ]\n  }\n]\n', NULL, NULL, NULL, NULL, NULL, 'https://h5p.org/speak-the-words-set', 1);
