INSERT INTO `mdl_notifications` (`id`, `useridfrom`, `useridto`, `subject`, `fullmessage`, `fullmessageformat`, `fullmessagehtml`, `smallmessage`, `component`, `eventtype`, `contexturl`, `contexturlname`, `timeread`, `timecreated`, `customdata`) VALUES
(6, 2, 2, 'Moodle updates are available (http://localhost/moodle)', 'Update notifications\r\n\r\nThere is a newer Moodle version available!\r\nMoodle 5.1.3+ (Build: 20260415) Version 2025100603.13 (Stable version)\r\n\r\nSee http://localhost/moodle/admin/index.php for more details\r\n\r\nIt is strongly recommended that you update your site to the latest version to obtain all recent security and bug fixes.\r\n\r\nYour Moodle site http://localhost/moodle is configured to automatically check for available updates. You are receiving this message as the administrator of the site. You can disable automatic checks for available updates in Site administration / Server / Update notifications or customise the delivery of this message via your preferences page.\r\n', 2, '<h1>Update notifications</h1>\r\n<h2>There is a newer Moodle version available!</h2>\r\n<ul>\r\n<li><strong>Moodle 5.1.3+ (Build: 20260415)</strong> Version 2025100603.13 (Stable version)</li>\r\n</ul>\r\n<p>See <a href=\"http://localhost/moodle/admin/index.php\">http://localhost/moodle/admin/index.php</a> for more details</p>\r\n<p>It is strongly recommended that you update your site to the latest version to obtain all recent security and bug fixes.</p>\r\n<footer><p style=\"font-size:smaller; color:#333;\">Your Moodle site <a href=\"http://localhost/moodle\">http://localhost/moodle</a> is configured to automatically check for available updates. You are receiving this message as the administrator of the site. You can disable automatic checks for available updates in Site administration / Server / Update notifications or customise the delivery of this message via your preferences page.</p></footer>', 'Update notifications', 'moodle', 'availableupdate', NULL, NULL, NULL, 1776338518, NULL),
(7, -10, 3, 'New sign in to your Faishal Hidayat Page account', 'Hi Faishal Hidayat,\n\nYour Faishal Hidayat Page account was just signed in to from a new device.\n\n	* Your account: teacher1 faishalhidayad@gmail.com\n	* Wednesday, 1 April 2026, 9:10 PM\n	* Device: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36\n(KHTML, like Gecko) Chrome/146.0.0.0 Safari/537.36 Edg/146.0.0.0\n	* IP: 0:0:0:0:0:0:0:1\n\nIf this was you, then you don\'t need to do anything.\n\nIf you don\'t recognise this activity, please change your password [1].\n\n\nLinks:\n------\n[1] http://localhost/moodle/login/change_password.php\n', 1, '<p>Hi Faishal Hidayat,</p>\n<p>Your Faishal Hidayat Page account was just signed in to from a new device.</p>\n<ul>\n<li>Your account: teacher1 faishalhidayad@gmail.com</li>\n<li>Wednesday, 1 April 2026, 9:10 PM</li>\n<li>Device:  Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/146.0.0.0 Safari/537.36 Edg/146.0.0.0</li>\n<li>IP: 0:0:0:0:0:0:0:1</li>\n</ul>\n<p>If this was you, then you don\'t need to do anything.</p>\n<p>If you don\'t recognise this activity, please <a href=\"http://localhost/moodle/login/change_password.php\">change your password</a>.</p>', 'Your teacher1 account was just signed in to from a new device.', 'moodle', 'newlogin', NULL, NULL, NULL, 1776338538, '{\"notificationiconurl\":\"http:\\/\\/localhost\\/moodle\\/tokenpluginfile.php\\/3be45386094f3de5925bbd401f491fc7\\/24\\/user\\/icon\\/boost\\/f1?rev=210\",\"courseid\":\"1\"}'),
(8, 2, 2, 'Moodle Restore completed successfully', 'Restore (ID: 09e78d6f2d8743699135ef5b5c40ff8e) completed. Access it here:\nhttp://localhost/moodle/course/view.php?id=4 [1].\n\nLinks:\n------\n[1] http://localhost/moodle/course/view.php?id=4\n', 1, 'Restore (ID: 09e78d6f2d8743699135ef5b5c40ff8e) completed. Access it here: <a href=\"http://localhost/moodle/course/view.php?id=4\">http://localhost/moodle/course/view.php?id=4</a>.', '', 'moodle', 'asyncbackupnotification', NULL, NULL, NULL, 1776338569, NULL),
(9, 2, 2, 'Moodle Restore completed successfully', 'Restore (ID: 92ac34e831eaaff2882a34d95b89a692) completed. Access it here:\nhttp://localhost/moodle/course/view.php?id=5 [1].\n\nLinks:\n------\n[1] http://localhost/moodle/course/view.php?id=5\n', 1, 'Restore (ID: 92ac34e831eaaff2882a34d95b89a692) completed. Access it here: <a href=\"http://localhost/moodle/course/view.php?id=5\">http://localhost/moodle/course/view.php?id=5</a>.', '', 'moodle', 'asyncbackupnotification', NULL, NULL, NULL, 1776339712, NULL),
(10, 2, 2, 'Moodle Restore completed successfully', 'Restore (ID: fd35b93454523609b896755cbb0d76c0) completed. Access it here:\nhttp://localhost/moodle/course/view.php?id=6 [1].\n\nLinks:\n------\n[1] http://localhost/moodle/course/view.php?id=6\n', 1, 'Restore (ID: fd35b93454523609b896755cbb0d76c0) completed. Access it here: <a href=\"http://localhost/moodle/course/view.php?id=6\">http://localhost/moodle/course/view.php?id=6</a>.', '', 'moodle', 'asyncbackupnotification', NULL, NULL, NULL, 1776340159, NULL),
(11, -20, 3, 'Students at risk in Jurusan Teknik Komputer dan Jaringan course', 'Hi Faishal,\n<p>A number of students in Jurusan Teknik Komputer dan Jaringan have not accessed the course recently.</p>\r\n\r\nhttp://localhost/moodle/report/insights/insights.php?modelid=5&contextid=31', 2, '<head><style>\nbody:not(.dir-ltr):not(.dir-rtl) {\n    font-family: \'Open Sans\', sans-serif;\n}\n.btn-insight {\n    color: #007bff;\n    background-color: transparent;\n    display: inline-block;\n    font-weight: 400;\n    text-align: center;\n    white-space: nowrap;\n    vertical-align: middle;\n    user-select: none;\n    border: 1px solid #007bff;\n    padding: .375rem .75rem;\n    line-height: 1.5;\n    border-radius: 0;\n    text-decoration: none;\n    cursor: pointer;\n}\n</style></head>\n\nHi Faishal,\n<p>A number of students in Jurusan Teknik Komputer dan Jaringan have not accessed the course recently.</p>\n<br/><br/>\n<a class=\"btn btn-outline-primary btn-insight\" href=\"http://localhost/moodle/report/insights/insights.php?modelid=5&amp;contextid=31\">View insight</a>', 'Hi Faishal,\n<p>A number of students in Jurusan Teknik Komputer dan Jaringan have not accessed the course recently.</p>\r\n\r\nhttp://localhost/moodle/report/insights/insights.php?modelid=5&contextid=31', 'moodle', 'insights', 'http://localhost/moodle/report/insights/insights.php?modelid=5&contextid=31', 'Students at risk in Jurusan Teknik Komputer dan Jaringan course', NULL, 1778036111, NULL),
(12, -20, 2, 'Students at risk in Jurusan Teknik Komputer dan Jaringan course', 'Hi Admin,\n<p>A number of students in Jurusan Teknik Komputer dan Jaringan have not accessed the course recently.</p>\r\n\r\nhttp://localhost/moodle/report/insights/insights.php?modelid=5&contextid=31', 2, '<head><style>\nbody:not(.dir-ltr):not(.dir-rtl) {\n    font-family: \'Open Sans\', sans-serif;\n}\n.btn-insight {\n    color: #007bff;\n    background-color: transparent;\n    display: inline-block;\n    font-weight: 400;\n    text-align: center;\n    white-space: nowrap;\n    vertical-align: middle;\n    user-select: none;\n    border: 1px solid #007bff;\n    padding: .375rem .75rem;\n    line-height: 1.5;\n    border-radius: 0;\n    text-decoration: none;\n    cursor: pointer;\n}\n</style></head>\n\nHi Admin,\n<p>A number of students in Jurusan Teknik Komputer dan Jaringan have not accessed the course recently.</p>\n<br/><br/>\n<a class=\"btn btn-outline-primary btn-insight\" href=\"http://localhost/moodle/report/insights/insights.php?modelid=5&amp;contextid=31\">View insight</a>', 'Hi Admin,\n<p>A number of students in Jurusan Teknik Komputer dan Jaringan have not accessed the course recently.</p>\r\n\r\nhttp://localhost/moodle/report/insights/insights.php?modelid=5&contextid=31', 'moodle', 'insights', 'http://localhost/moodle/report/insights/insights.php?modelid=5&contextid=31', 'Students at risk in Jurusan Teknik Komputer dan Jaringan course', NULL, 1778036114, NULL),
(13, 2, 2, 'Moodle Backup completed successfully', 'Backup (ID: db679fdada4e06e0976a9d14b2155952) completed. Access it here:\nhttp://localhost/moodle/backup/restorefile.php?contextid=343 [1].\n\nLinks:\n------\n[1] http://localhost/moodle/backup/restorefile.php?contextid=343\n', 1, 'Backup (ID: db679fdada4e06e0976a9d14b2155952) completed. Access it here: <a href=\"http://localhost/moodle/backup/restorefile.php?contextid=343\">http://localhost/moodle/backup/restorefile.php?contextid=343</a>.', '', 'moodle', 'asyncbackupnotification', NULL, NULL, NULL, 1778036148, NULL),
