INSERT INTO `mdl_tiny_autosave` (`id`, `elementid`, `contextid`, `pagehash`, `userid`, `drafttext`, `draftid`, `pageinstance`, `timemodified`) VALUES
(6, 'id_summary_editor', 3, '32577b0e63e33ad39dfe17856a5935a79c49cafb', 2, '', 368890420, 'c7eccc39ef02a6858ed5680e821a2316', 1773722842),
(7, 'id_introeditor', 2, '4a76080e67ea221d6da5ccc8c89671aba18286ca', 2, '<p style=\"text-align: center;\"><strong>SILABUS MATA PELAJARAN</strong></p>\n<p>Nama Sekolah: SMK Negeri 1 Sidoarjo</p>\n<p>Bidang Keahlian: Teknologi Informasi dan Komunikasi</p>\n<p>Kompetensi Keahlian: Teknik Komputer dan Jaringan</p>\n<p>Mata Pelajaran: Administrasi Sistem Jaringan</p>\n<p>Durasi (Waktu): 488 JP</p>\n<p>Kelas/Semester: XII (Duabelas)/Ganjil </p>\n<p>KI-3 (Pengetahuan):Memahami, menerapkan, menganalisis, dan mengevaluasi tentang pengetahuan faktual, konseptual, operasionaldasar, dan metakognitif sesuai dengan bidang dan lingkup kerja Teknik Komputer dan Jaringan pada tingkat teknis,spesifik, detil, dan kompleks, berkenaan dengan ilmu pengetahuan, teknologi, seni, budaya, dan humaniora dalamkonteks pengembangan potensi diri sebagai bagian dari keluarga, sekolah, dunia kerja, warga masyarakat nasional,regional, dan internasional</p>\n<p>KI-4 (Keterampilan):Melaksanakan tugas spesifik dengan menggunakan alat, informasi, dan prosedur kerja yang lazim dilakukan sertamemecahkan masalah sesuai dengan bidang kerja Teknik Komputer dan Jaringan. Menampilkan kinerja di bawah bimbingan dengan mutu dan kuantitas yang terukur sesuai dengan standar kompetensi kerja.Menunjukkan keterampilan menalar, mengolah, dan menyaji secara efektif, kreatif, produktif, kritis, mandiri,kolaboratif, komunikatif, dan solutif dalam ranah abstrak terkait dengan pengembangan dari yang dipelajarinya disekolah, serta mampu melaksanakan tugas spesifik di bawah pengawasan langsung.Menunjukkan keterampilan mempersepsi, kesiapan, meniru, membiasakan, gerak mahir, menjadikan gerak alamidalam ranah konkret terkait dengan pengembangan dari yang dipelajarinya di sekolah, serta mampu melaksanakantugas spesifik di bawah pengawasan langsung</p>\n<p></p>', 711634078, 'ffbb78f1e84ea7677a83c6a35eae8ff5', 1773748128),
(8, 'id_page', 2, '4a76080e67ea221d6da5ccc8c89671aba18286ca', 2, '', 423017514, '90c661fed36b462912dc08cc669952ae', 1773748128),
