(267, 'id_summary_editor', 31, '97557c5744b0cb2263ec8f25afb858be8f66c288', 2, '', 921202439, '841c1dbe239c650be7aeb3a6aaa1bc45', 1775052276),
(268, 'id_message', 32, '103a20b1ddc8a376c4cccb48b2cc0e78700f0164', 2, '', 344135954, '3b6469672eb292f5a6869e159ebf36b8', 1775052342),
(290, 'id_message', 20, '4c43565ff1c951ee23da727717665f6bafc8f05e', 3, '', 226657171, '8f5dbb0c13e08d58aa1811a0bf7eb5f9', 1775054932),
(291, 'id_introeditor', 20, '15159bece2cccdb68ef5266774e012b76124018e', 3, '<p data-start=\"308\" data-end=\"373\"><strong data-start=\"308\" data-end=\"324\">Forum 1:</strong><br data-start=\"324\" data-end=\"327\">Forum Diskusi : Konsep Dasar Jaringan Komputer</p>\n<p data-start=\"375\" data-end=\"395\"><strong data-start=\"375\" data-end=\"395\">Deskripsi Forum:</strong></p>\n<p data-start=\"397\" data-end=\"456\">Silakan diskusikan mengenai konsep dasar jaringan komputer.</p>\n<ol data-start=\"458\" data-end=\"699\">\n<li data-section-id=\"1sj5am1\" data-start=\"458\" data-end=\"524\">Jelaskan pengertian jaringan komputer menurut pemahaman Anda.</li>\n<li data-section-id=\"zyc0lp\" data-start=\"525\" data-end=\"613\">Mengapa jaringan komputer sangat penting dalam lingkungan sekolah atau perkantoran?</li>\n<li data-section-id=\"1xzt78b\" data-start=\"614\" data-end=\"699\">Berikan contoh penerapan jaringan komputer yang pernah Anda lihat secara langsung<br><br></li>\n</ol>\n<p data-start=\"701\" data-end=\"844\">Tuliskan jawaban dengan bahasa yang jelas dan disertai penjelasan singkat<br data-start=\"775\" data-end=\"778\">Minimal 1 postingan utama dan 1 tanggapan terhadap pendapat teman</p>\n<p data-start=\"701\" data-end=\"844\"></p>\n<p data-start=\"917\" data-end=\"983\"><strong data-start=\"917\" data-end=\"933\">Forum 2 :</strong><br data-start=\"933\" data-end=\"936\">Forum Diskusi : Instalasi Sistem Operasi Server</p>\n<p data-start=\"985\" data-end=\"1005\"><strong data-start=\"985\" data-end=\"1005\">Deskripsi Forum:</strong></p>\n<p data-start=\"1007\" data-end=\"1098\">Setelah mempelajari materi instalasi sistem operasi server, silakan diskusikan hal berikut:</p>\n<ol data-start=\"1100\" data-end=\"1338\">\n<li data-section-id=\"vr3pjr\" data-start=\"1100\" data-end=\"1177\">Apa perbedaan sistem operasi server dengan sistem operasi desktop biasa?</li>\n<li data-section-id=\"r3g99a\" data-start=\"1178\" data-end=\"1272\">Mengapa pemilihan spesifikasi perangkat keras penting sebelum melakukan instalasi server?</li>\n<li data-section-id=\"p2w7wq\" data-start=\"1273\" data-end=\"1338\">Apa kendala yang mungkin terjadi saat proses instalasi server?<br><br></li>\n</ol>\n<p data-start=\"1340\" data-end=\"1500\">Jelaskan pendapat Anda berdasarkan materi yang telah dipelajari<br data-start=\"1404\" data-end=\"1407\">Berikan tanggapan terhadap minimal satu jawaban teman dengan komentar yang sopan dan relevan</p>\n<p data-start=\"1973\" data-end=\"2120\"></p>\n<p data-start=\"1340\" data-end=\"1500\"></p>', NULL, '9b996f16a9137a163214930c76cee9ff', 1775054955),
(293, 'id_summary_editor', 31, '3bbfd0f2d65f533a7ad326c176a1016fc3789b0b', 2, '', 502030289, '08d0a562bc460fc3ab11242e927b64e8', 1775055213),
